TYPE ST_StopJournalPersistent :
STRUCT
    a_stQueue        : ARRAY[0..127] OF ST_StopJournalEvent;
    uiHead           : UINT;
    uiTail           : UINT;
    uiCount          : UINT;
    udiNextEventId   : UDINT;
    udiOverflowCount : UDINT;
    uliLinePulses    : ULINT;
    wLastState       : WORD;
    dwSignature      : DWORD;
END_STRUCT
END_TYPE

ST.html:xhtml:
// 100 мм соответствуют 0.1 м на экране DWIN.
uliCurrentX10 := i_uliCurrentLengthMm / ULINT#100;
uliPreviousX10 := i_uliPreviousLengthMm / ULINT#100;
IF (i_uliPreviousLengthMm MOD ULINT#100) >= ULINT#50 THEN
    uliPreviousX10 := uliPreviousX10 + ULINT#1;
END_IF;
q_xOverflow := FALSE;


IF uliCurrentX10 > c_uliDwinMaxValue THEN
    udiCurrentX10 := UDINT#4294967295;
    q_xOverflow := TRUE;
ELSE
    udiCurrentX10 := ULINT_TO_UDINT(uliCurrentX10);
END_IF;


IF uliPreviousX10 > c_uliDwinMaxValue THEN
    udiPreviousX10 := UDINT#4294967295;
    q_xOverflow := TRUE;
ELSE
    udiPreviousX10 := ULINT_TO_UDINT(uliPreviousX10);
END_IF;


q_wCurrentHigh :=
    UDINT_TO_WORD(udiCurrentX10 / UDINT#65536);

q_wCurrentLow :=
    UDINT_TO_WORD(udiCurrentX10 MOD UDINT#65536);

q_wPreviousHigh :=
    UDINT_TO_WORD(udiPreviousX10 / UDINT#65536);

q_wPreviousLow :=
    UDINT_TO_WORD(udiPreviousX10 MOD UDINT#65536);

q_wUnwindNumber := USINT_TO_WORD(i_usiUnwindNumber);

q_xPacketValid := FALSE;

FOR iWord := 0 TO 11 DO
    q_a_wPacket[iWord] := WORD#0;
END_FOR;


IF i_xEventValid THEN

    // 0: сигнатура; 1: версия протокола.
    q_a_wPacket[0] := c_wSignature;
    q_a_wPacket[1] := c_wProtocolVersion;

    // 2...3: EventId UDINT, старшее слово идёт первым.
    q_a_wPacket[2] := UDINT_TO_WORD(i_stEvent.udiEventId / UDINT#65536);
    q_a_wPacket[3] := UDINT_TO_WORD(i_stEvent.udiEventId MOD UDINT#65536);

    // 4...5: UNIX-время UTC UDINT, старшее слово идёт первым.
    q_a_wPacket[4] := UDINT_TO_WORD(i_stEvent.udiTimestampUtc / UDINT#65536);
    q_a_wPacket[5] := UDINT_TO_WORD(i_stEvent.udiTimestampUtc MOD UDINT#65536);

    // 6...8: физический раскат, смена и причина передаются отдельными словами.
    q_a_wPacket[6] := USINT_TO_WORD(i_stEvent.usiUnwindNumber);
    q_a_wPacket[7] := USINT_TO_WORD(i_stEvent.usiShiftNumber);

    CASE i_stEvent.eEndReason OF
        ROLL_END_SPLICE:
            q_a_wPacket[8] := WORD#1;
        ROLL_END_RESET:
            q_a_wPacket[8] := WORD#2;
        ELSE
            q_a_wPacket[8] := WORD#0;
    END_CASE;

    // 9...10: длина завершённого рулона в миллиметрах, UDINT.
    q_a_wPacket[9] := UDINT_TO_WORD(i_stEvent.udiLengthMm / UDINT#65536);
    q_a_wPacket[10] := UDINT_TO_WORD(i_stEvent.udiLengthMm MOD UDINT#65536);


    // CRC16 Modbus по словам 0...10. В каждом слове сначала обрабатывается старший байт.
    wCrc := WORD#16#FFFF;

    FOR iWord := 0 TO 10 DO

        wSourceWord := q_a_wPacket[iWord];

        FOR iByte := 0 TO 1 DO

            IF iByte = 0 THEN
                byData := WORD_TO_BYTE(SHR(wSourceWord, 8));
            ELSE
                byData := WORD_TO_BYTE(wSourceWord AND WORD#16#00FF);
            END_IF;

            wCrc := wCrc XOR BYTE_TO_WORD(byData);

            FOR iBit := 0 TO 7 DO
                IF (wCrc AND WORD#1) <> WORD#0 THEN
                    wCrc := SHR(wCrc, 1) XOR WORD#16#A001;
                ELSE
                    wCrc := SHR(wCrc, 1);
                END_IF;
            END_FOR;

        END_FOR;

    END_FOR;

    q_a_wPacket[11] := wCrc;
    q_xPacketValid := TRUE;

END_IF;

// Одноцикловые и расчётные поля сначала сбрасываются.
iq_stState.udiPulseDelta := UDINT#0;
iq_stState.xDataValid := FALSE;
iq_stState.xJumpDetected := FALSE;
uliCalculatedDelta := ULINT#0;


// Проверяем параметры самого трекера.
IF (i_udiCounterRange = UDINT#0)
   OR (i_udiMaxDeltaPerCycle = UDINT#0) THEN

    iq_stState.eStatus := CHANNEL_STATUS_CONFIG_ERROR;


// Ошибка HSC имеет приоритет над признаком Validity.
ELSIF i_xHscError THEN

    iq_stState.eStatus := CHANNEL_STATUS_HSC_ERROR;


ELSIF NOT i_xHscValid THEN

    iq_stState.eStatus := CHANNEL_STATUS_HSC_INVALID;


// Первый исправный отсчёт используется только как начальная точка.
ELSIF NOT iq_stState.xInitialized THEN

    iq_stState.udiPreviousAbs := i_udiHscAbs;
    iq_stState.xInitialized := TRUE;
    iq_stState.xDataValid := TRUE;
    iq_stState.eStatus := CHANNEL_STATUS_RUNNING;


ELSE

    // Обычное приращение без перехода HSC через ноль.
    IF i_udiHscAbs >= iq_stState.udiPreviousAbs THEN

        uliCalculatedDelta :=
            UDINT_TO_ULINT(i_udiHscAbs)
            - UDINT_TO_ULINT(iq_stState.udiPreviousAbs);


    // Переход через заданный диапазон HSC.
    ELSIF iq_stState.udiPreviousAbs < i_udiCounterRange THEN

        uliCalculatedDelta :=
            (
                UDINT_TO_ULINT(i_udiCounterRange)
                - UDINT_TO_ULINT(iq_stState.udiPreviousAbs)
            )
            + UDINT_TO_ULINT(i_udiHscAbs);


    // Значение не соответствует настроенному диапазону.
    ELSE

        uliCalculatedDelta :=
            UDINT_TO_ULINT(i_udiMaxDeltaPerCycle) + ULINT#1;

    END_IF;


    // Запоминаем текущий абсолютный отсчёт как базу следующего цикла.
    iq_stState.udiPreviousAbs := i_udiHscAbs;


    // Реалистичное приращение разрешается использовать дальше.
    IF uliCalculatedDelta <= UDINT_TO_ULINT(i_udiMaxDeltaPerCycle) THEN

        iq_stState.udiPulseDelta :=
            ULINT_TO_UDINT(uliCalculatedDelta);

        iq_stState.xDataValid := TRUE;
        iq_stState.eStatus := CHANNEL_STATUS_RUNNING;


    // Огромный скачок отбрасывается и не попадает в метраж.
    ELSE

        iq_stState.xJumpDetected := TRUE;
        iq_stState.udiRejectedJumpCount :=
            iq_stState.udiRejectedJumpCount + UDINT#1;

        iq_stState.eStatus := CHANNEL_STATUS_COUNTER_JUMP;

    END_IF;

END_IF;

fbOnDelay(
    IN := i_xRaw,
    PT := i_tOnDelay
);

q_xFiltered := fbOnDelay.Q;

iq_stState.xConfigFault :=
    (i_udiPulsesPerRevolution = UDINT#0)
    OR (i_udiWheelCircumferenceMm = UDINT#0)
    OR (i_tSpeedSample <= T#0ms);


// Накапливаем общий метраж и окно скорости только по исправным данным.
IF i_xPulseDataValid AND NOT iq_stState.xConfigFault THEN

    iq_stState.uliTotalPulses :=
        iq_stState.uliTotalPulses
        + UDINT_TO_ULINT(i_udiPulseDelta);

    uliWindowPulses :=
        uliWindowPulses
        + UDINT_TO_ULINT(i_udiPulseDelta);


    uliTotalLengthValue :=
        iq_stState.uliTotalPulses
        * UDINT_TO_ULINT(i_udiWheelCircumferenceMm);

    iq_stState.uliTotalLengthMm :=
        uliTotalLengthValue
        / UDINT_TO_ULINT(i_udiPulsesPerRevolution);

END_IF;


// Самоперезапускающийся таймер выдаёт импульс примерно раз в i_tSpeedSample.
fbSpeedSample(
    IN := NOT fbSpeedSample.Q,
    PT := i_tSpeedSample
);


IF fbSpeedSample.Q THEN

    IF NOT iq_stState.xConfigFault AND i_xPulseDataValid THEN

        uliWindowLengthMm :=
            (
                uliWindowPulses
                * UDINT_TO_ULINT(i_udiWheelCircumferenceMm)
            )
            / UDINT_TO_ULINT(i_udiPulsesPerRevolution);

        udiSampleTimeMs := TIME_TO_UDINT(i_tSpeedSample);


        // мм * 60 / мс = метров в минуту.
        iq_stState.rSpeedMPerMin :=
            ULINT_TO_REAL(uliWindowLengthMm)
            * 60.0
            / UDINT_TO_REAL(udiSampleTimeMs);

        iq_stState.xMoving := uliWindowPulses > ULINT#0;

    ELSE

        iq_stState.rSpeedMPerMin := 0.0;
        iq_stState.xMoving := FALSE;

    END_IF;


    uliWindowPulses := ULINT#0;

END_IF;

// Эти признаки активны только один цикл программы.
iq_stState.xRollCompleted := FALSE;
iq_stState.xShortResetDiscarded := FALSE;
xSpliceRising := FALSE;
xResetRising := FALSE;


// После запуска обе кнопки должны хотя бы один раз быть отпущены.
// Это не позволяет зажатой кнопке завершить рулон при старте ПЛК.
IF NOT xCommandsArmed THEN

    IF NOT i_xSplice AND NOT i_xReset THEN
        xCommandsArmed := TRUE;
    END_IF;

ELSE

    xSpliceRising := i_xSplice AND NOT xPreviousSplice;
    xResetRising := i_xReset AND NOT xPreviousReset;

END_IF;


// Проверяем параметры пересчёта.
iq_stState.xConfigFault :=
    (i_udiPulsesPerRevolution = UDINT#0)
    OR (i_udiWheelCircumferenceMm = UDINT#0);


// Нумерация внутренних рулонов каждого канала начинается с единицы.
IF iq_stState.udiRollSequenceNumber = UDINT#0 THEN
    iq_stState.udiRollSequenceNumber := UDINT#1;
END_IF;


// Накапливаем только достоверное приращение HSC.
IF i_xPulseDataValid AND NOT iq_stState.xConfigFault THEN

    iq_stState.uliCurrentRollPulses :=
        iq_stState.uliCurrentRollPulses
        + UDINT_TO_ULINT(i_udiPulseDelta);


    // импульсы * окружность / импульсов на оборот = миллиметры
    uliLengthValue :=
        iq_stState.uliCurrentRollPulses
        * UDINT_TO_ULINT(i_udiWheelCircumferenceMm);

    iq_stState.uliCurrentLengthMm :=
        uliLengthValue
        / UDINT_TO_ULINT(i_udiPulsesPerRevolution);

END_IF;


// SPLICE всегда завершает рулон.
// RESET завершает рулон только при достижении установленного порога.
IF NOT iq_stState.xConfigFault
   AND
   (
       xSpliceRising
       OR
       (
           xResetRising
           AND
           (iq_stState.uliCurrentLengthMm >= i_uliManualResetMinLengthMm)
       )
   ) THEN

    iq_stState.uliPreviousRollPulses :=
        iq_stState.uliCurrentRollPulses;

    iq_stState.uliPreviousRollLengthMm :=
        iq_stState.uliCurrentLengthMm;


    iq_stState.uliCurrentRollPulses := ULINT#0;
    iq_stState.uliCurrentLengthMm := ULINT#0;


    IF iq_stState.udiRollSequenceNumber < UDINT#4294967295 THEN
        iq_stState.udiRollSequenceNumber :=
            iq_stState.udiRollSequenceNumber + UDINT#1;
    ELSE
        iq_stState.udiRollSequenceNumber := UDINT#1;
    END_IF;


    IF xSpliceRising THEN
        iq_stState.eLastEndReason := ROLL_END_SPLICE;
    ELSE
        iq_stState.eLastEndReason := ROLL_END_RESET;
    END_IF;


    iq_stState.xRollCompleted := TRUE;


// Короткий ручной RESET очищает только текущий рулон.
// Предыдущий учтённый рулон и номер последовательности не изменяются.
ELSIF NOT iq_stState.xConfigFault AND xResetRising THEN

    iq_stState.uliLastDiscardedLengthMm :=
        iq_stState.uliCurrentLengthMm;

    iq_stState.uliDiscardedTotalLengthMm :=
        iq_stState.uliDiscardedTotalLengthMm
        + iq_stState.uliCurrentLengthMm;

    iq_stState.uliCurrentRollPulses := ULINT#0;
    iq_stState.uliCurrentLengthMm := ULINT#0;
    iq_stState.xShortResetDiscarded := TRUE;

END_IF;


// Запоминаем уровни кнопок для обнаружения следующего фронта.
xPreviousSplice := i_xSplice;
xPreviousReset := i_xReset;

// Одноцикловые выходы сбрасываются в начале каждого вызова.
q_xAckAccepted := FALSE;
q_xAckRejected := FALSE;
q_xAckCommandConsumed := FALSE;
q_xEventIdExhausted := FALSE;

FOR iChannel := 1 TO 5 DO
    q_a_xEnqueued[iChannel] := FALSE;
END_FOR;


// Проверяем целостность служебных данных, восстановленных после включения ПЛК.
q_xStorageFault :=
    (iq_uiQueueHead > c_uiLastQueueIndex)
    OR (iq_uiQueueTail > c_uiLastQueueIndex)
    OR (iq_uiQueueCount > c_uiQueueCapacity)
    OR (iq_udiNextEventId = UDINT#0);


IF NOT q_xStorageFault THEN

    // Сначала обрабатываем подтверждение, чтобы при полной очереди
    // в этом же цикле освободилось место для нового события.
    IF i_wAckCommand = c_wAckCommand THEN

        q_xAckCommandConsumed := TRUE;

        IF (iq_uiQueueCount > UINT#0)
           AND (iq_a_stQueue[iq_uiQueueHead].udiEventId = i_udiAckEventId) THEN

            IF iq_uiQueueHead >= c_uiLastQueueIndex THEN
                iq_uiQueueHead := UINT#0;
            ELSE
                iq_uiQueueHead := iq_uiQueueHead + UINT#1;
            END_IF;

            iq_uiQueueCount := iq_uiQueueCount - UINT#1;
            q_xAckAccepted := TRUE;

        ELSE

            // Очередь пустая либо сервер подтвердил не текущее событие.
            q_xAckRejected := TRUE;

        END_IF;

    END_IF;


    // За один цикл могут одновременно завершиться несколько раскатов.
    FOR iChannel := 1 TO 5 DO

        IF i_a_xEnqueue[iChannel] THEN

            IF (iq_uiQueueCount < c_uiQueueCapacity)
               AND (iq_udiNextEventId < c_udiMaxEventId) THEN

                stEventToAdd := i_a_stEvent[iChannel];
                stEventToAdd.udiEventId := iq_udiNextEventId;

                iq_a_stQueue[iq_uiQueueTail] := stEventToAdd;

                IF iq_uiQueueTail >= c_uiLastQueueIndex THEN
                    iq_uiQueueTail := UINT#0;
                ELSE
                    iq_uiQueueTail := iq_uiQueueTail + UINT#1;
                END_IF;

                iq_uiQueueCount := iq_uiQueueCount + UINT#1;
                iq_udiNextEventId := iq_udiNextEventId + UDINT#1;
                q_a_xEnqueued[iChannel] := TRUE;

            ELSIF iq_udiNextEventId >= c_udiMaxEventId THEN

                // Теоретическая защита; в реальной эксплуатации этот предел недостижим.
                q_xEventIdExhausted := TRUE;

            ELSE

                // Очередь заполнена: событие не перезаписывает более старые данные.
                IF iq_udiOverflowCount < UDINT#4294967295 THEN
                    iq_udiOverflowCount := iq_udiOverflowCount + UDINT#1;
                END_IF;

            END_IF;

        END_IF;

    END_FOR;

END_IF;


// Сервер всегда видит только первое неподтверждённое событие.
q_uiQueueCount := iq_uiQueueCount;
q_xQueueFull := iq_uiQueueCount >= c_uiQueueCapacity;
q_xEventReady := (iq_uiQueueCount > UINT#0) AND NOT q_xStorageFault;

IF q_xEventReady THEN
    q_stCurrentEvent := iq_a_stQueue[iq_uiQueueHead];
ELSE
    q_stCurrentEvent := stEmptyEvent;
END_IF;

iq_stState.xShiftChanged := FALSE;


// GetRtc входит в уже подключённую библиотеку M241 PLCSystem.
// В текущем проекте пространство имён этой библиотеки — SEC.
diUtcTimestamp := SEC.GetRtc();


IF (diUtcTimestamp > DINT#0)
   AND (i_usiShift1StartHour < USINT#24)
   AND (i_usiShift2StartHour < USINT#24)
   AND (i_usiShift1StartHour < i_usiShift2StartHour) THEN

    udiUtcTimestamp := DINT_TO_UDINT(diUtcTimestamp);
    iq_stState.udiTimestampUtc := udiUtcTimestamp;
    iq_stState.udiRtcError := UDINT#0;

    udiLocalTimestamp := udiUtcTimestamp + i_udiUtcOffsetSeconds;
    udiLocalSecondsDay := udiLocalTimestamp MOD UDINT#86400;


    iq_stState.uiLocalHour :=
        UDINT_TO_UINT(udiLocalSecondsDay / UDINT#3600);

    iq_stState.uiLocalMinute :=
        UDINT_TO_UINT(
            (udiLocalSecondsDay MOD UDINT#3600)
            / UDINT#60
        );

    iq_stState.uiLocalSecond :=
        UDINT_TO_UINT(udiLocalSecondsDay MOD UDINT#60);


    // Календарная дата рассчитывается из целого числа дней UNIX-времени.
    // Цикл ограничен текущим диапазоном UDINT и выполняется не более 137 раз.
    udiDaysRemaining := udiLocalTimestamp / UDINT#86400;
    uiYear := UINT#1970;

    xLeapYear :=
        ((uiYear MOD UINT#4) = UINT#0)
        AND
        (
            ((uiYear MOD UINT#100) <> UINT#0)
            OR ((uiYear MOD UINT#400) = UINT#0)
        );
    IF xLeapYear THEN
        uiDaysInYear := UINT#366;
    ELSE
        uiDaysInYear := UINT#365;
    END_IF;

    WHILE udiDaysRemaining >= UINT_TO_UDINT(uiDaysInYear) DO
        udiDaysRemaining :=
            udiDaysRemaining - UINT_TO_UDINT(uiDaysInYear);
        uiYear := uiYear + UINT#1;

        xLeapYear :=
            ((uiYear MOD UINT#4) = UINT#0)
            AND
            (
                ((uiYear MOD UINT#100) <> UINT#0)
                OR ((uiYear MOD UINT#400) = UINT#0)
            );
        IF xLeapYear THEN
            uiDaysInYear := UINT#366;
        ELSE
            uiDaysInYear := UINT#365;
        END_IF;
    END_WHILE;

    uiMonth := UINT#1;
    WHILE uiMonth <= UINT#12 DO
        CASE uiMonth OF
            UINT#2:
                IF xLeapYear THEN
                    uiDaysInMonth := UINT#29;
                ELSE
                    uiDaysInMonth := UINT#28;
                END_IF;
            UINT#4, UINT#6, UINT#9, UINT#11:
                uiDaysInMonth := UINT#30;
            ELSE
                uiDaysInMonth := UINT#31;
        END_CASE;

        IF udiDaysRemaining < UINT_TO_UDINT(uiDaysInMonth) THEN
            EXIT;
        END_IF;

        udiDaysRemaining :=
            udiDaysRemaining - UINT_TO_UDINT(uiDaysInMonth);
        uiMonth := uiMonth + UINT#1;
    END_WHILE;

    iq_stState.uiLocalYear := uiYear;
    iq_stState.uiLocalMonth := uiMonth;
    iq_stState.uiLocalDay := UDINT_TO_UINT(udiDaysRemaining) + UINT#1;


    IF (iq_stState.uiLocalHour >= USINT_TO_UINT(i_usiShift1StartHour))
       AND (iq_stState.uiLocalHour < USINT_TO_UINT(i_usiShift2StartHour)) THEN

        usiNewShift := USINT#1;

    ELSE

        usiNewShift := USINT#2;

    END_IF;


    IF (iq_stState.usiCurrentShift <> USINT#0)
       AND (iq_stState.usiCurrentShift <> usiNewShift) THEN

        iq_stState.xShiftChanged := TRUE;

    END_IF;


    iq_stState.usiCurrentShift := usiNewShift;
    iq_stState.xRtcValid := TRUE;


ELSE

    iq_stState.xRtcValid := FALSE;
    iq_stState.usiCurrentShift := USINT#0;
    iq_stState.uiLocalHour := UINT#0;
    iq_stState.uiLocalMinute := UINT#0;
    iq_stState.uiLocalSecond := UINT#0;
    iq_stState.uiLocalYear := UINT#0;
    iq_stState.uiLocalMonth := UINT#0;
    iq_stState.uiLocalDay := UINT#0;
    iq_stState.udiTimestampUtc := UDINT#0;

    // 1 означает, что RTC ещё не содержит корректного UNIX-времени.
    IF diUtcTimestamp <= DINT#0 THEN
        iq_stState.udiRtcError := UDINT#1;
    ELSE
        // Максимальное значение означает ошибку настройки границ смен.
        iq_stState.udiRtcError := UDINT#4294967295;
    END_IF;

END_IF;

q_xAckConsumed := FALSE;
q_xAckAccepted := FALSE;
q_xAckRejected := FALSE;
q_xIdExhausted := FALSE;

q_xStorageFault :=
    (iq_uiHead > UINT#127)
    OR (iq_uiTail > UINT#127)
    OR (iq_uiCount > UINT#128)
    OR (iq_udiNextId = UDINT#0);

IF NOT q_xStorageFault THEN
    // Только подтверждение головы очереди освобождает событие.
    IF i_wAckCommand = WORD#16#A55B THEN
        q_xAckConsumed := TRUE;
        IF (iq_uiCount > UINT#0)
           AND (iq_a_stQueue[iq_uiHead].udiEventId = i_udiAckEventId) THEN
            IF iq_uiHead = UINT#127 THEN
                iq_uiHead := UINT#0;
            ELSE
                iq_uiHead := iq_uiHead + UINT#1;
            END_IF;
            iq_uiCount := iq_uiCount - UINT#1;
            q_xAckAccepted := TRUE;
        ELSE
            q_xAckRejected := TRUE;
        END_IF;
    END_IF;

    FOR iEvent := 1 TO 2 DO
        IF i_a_xEnqueue[iEvent] THEN
            IF (iq_uiCount < UINT#128)
               AND (iq_udiNextId < UDINT#4294967295) THEN
                stToAdd := i_a_stEvent[iEvent];
                stToAdd.udiEventId := iq_udiNextId;
                iq_a_stQueue[iq_uiTail] := stToAdd;
                IF iq_uiTail = UINT#127 THEN
                    iq_uiTail := UINT#0;
                ELSE
                    iq_uiTail := iq_uiTail + UINT#1;
                END_IF;
                iq_uiCount := iq_uiCount + UINT#1;
                iq_udiNextId := iq_udiNextId + UDINT#1;
            ELSIF iq_udiNextId >= UDINT#4294967295 THEN
                q_xIdExhausted := TRUE;
            ELSE
                IF iq_udiOverflow < UDINT#4294967295 THEN
                    iq_udiOverflow := iq_udiOverflow + UDINT#1;
                END_IF;
            END_IF;
        END_IF;
    END_FOR;
END_IF;

q_xFull := iq_uiCount >= UINT#128;
q_xReady := (iq_uiCount > UINT#0) AND NOT q_xStorageFault;
IF q_xReady THEN
    q_stHead := iq_a_stQueue[iq_uiHead];
ELSE
    q_stHead := stEmpty;
END_IF;

InterfaceAsPlainText.html:xhtml:
FUNCTION_BLOCK FB_StopJournalQueue
VAR_INPUT
    i_a_xEnqueue   : ARRAY[1..2] OF BOOL; // 1=граница смены, 2=переход состояния/заказ.
    i_a_stEvent    : ARRAY[1..2] OF ST_StopJournalEvent;
    i_udiAckEventId: UDINT;
    i_wAckCommand  : WORD;
END_VAR

VAR_IN_OUT
    iq_a_stQueue    : ARRAY[0..127] OF ST_StopJournalEvent;
    iq_uiHead       : UINT;
    iq_uiTail       : UINT;
    iq_uiCount      : UINT;
    iq_udiNextId    : UDINT;
    iq_udiOverflow  : UDINT;
END_VAR

VAR_OUTPUT
    q_xReady        : BOOL;
    q_stHead        : ST_StopJournalEvent;
    q_xFull         : BOOL;
    q_xStorageFault : BOOL;
    q_xIdExhausted  : BOOL;
    q_xAckConsumed  : BOOL;
    q_xAckAccepted  : BOOL;
    q_xAckRejected  : BOOL;
END_VAR

VAR
    iEvent          : INT;
    stToAdd         : ST_StopJournalEvent;
    stEmpty         : ST_StopJournalEvent;
END_VAR

ST.html:xhtml:
q_xCommandConsumed := FALSE;
q_xServerOrderCommandConsumed := FALSE;
q_xBreakRecorded := FALSE;
xBreakRecordedPulse := FALSE;


// При первом запуске либо после изменения структуры задаём безопасные значения.
IF iq_stPersistent.wConfigSignature <> GVL_Constants.c_wStopMachineSignature THEN
    iq_stPersistent.wConfigSignature := GVL_Constants.c_wStopMachineSignature;
    iq_stPersistent.udiOrderNumber := UDINT#0;
    iq_stPersistent.udiOrderDatabaseId := UDINT#0;
    iq_stPersistent.udiOrderTechnicalCard := UDINT#0;
    iq_stPersistent.uiOrderSourceShift := UINT#0;
    iq_stPersistent.uiOrderNominalSpeed := UINT#0;
    iq_stPersistent.uiOperatorNumber := UINT#0;
    iq_stPersistent.wLastServerOrderSequence := i_wServerOrderSequence;
    iq_stPersistent.uliOrderBaselineMm := i_uliTotalLengthMm;
    iq_stPersistent.uliShiftBaselineMm := i_uliTotalLengthMm;
    iq_stPersistent.uiAreaCoefficientX100 := GVL_Constants.c_uiStopDefaultAreaCoefficientX100;
    iq_stPersistent.uiStartDetectLengthDm := GVL_Constants.c_uiStopDefaultStartDetectLengthDm;
    iq_stPersistent.uiChangeoverSetpointTenthsMin := GVL_Constants.c_uiStopDefaultChangeoverTenthsMin;
    iq_stPersistent.usiLastShiftNumber := i_usiCurrentShift;
END_IF;


IF NOT iq_stState.xInitialized THEN
    // После перезапуска не объявляем работу до импульсов энкодера.
    // Известную ручную причину остановки, если она была, сохраняем.
    IF (i_wRestoredState = GVL_Constants.c_wStopStateStopped)
       OR (i_wRestoredState = GVL_Constants.c_wStopStateNoFeed)
       OR (i_wRestoredState = GVL_Constants.c_wStopStateChangeover)
       OR (i_wRestoredState = GVL_Constants.c_wStopStateProduction)
       OR (i_wRestoredState = GVL_Constants.c_wStopStatePpr)
       OR (i_wRestoredState = GVL_Constants.c_wStopStateLunch)
       OR (i_wRestoredState = GVL_Constants.c_wStopStateRepair)
       OR (i_wRestoredState = GVL_Constants.c_wStopStateAlarm)
       OR (i_wRestoredState = GVL_Constants.c_wStopStateTechnology)
       OR (i_wRestoredState = GVL_Constants.c_wStopStateBreak) THEN
        iq_stState.wStateCode := i_wRestoredState;
    ELSE
        iq_stState.wStateCode := WORD#0; // Пока не определено движение после запуска.
    END_IF;
    iq_stState.wLastCommandResult := GVL_Constants.c_wStopResultNone;
    iq_stState.wLastProcessedSequence := i_wCommandSequence;
    iq_stState.wLastServerOrderResult := WORD#0;
    iq_stState.wLastServerOrderSequence := iq_stPersistent.wLastServerOrderSequence;
    iq_stState.xServerOrderValid := iq_stPersistent.udiOrderDatabaseId <> UDINT#0;
    iq_stState.xPackingComplete := FALSE;
    iq_stState.xCommandRejected := FALSE;
    uliRunDetectBaselineMm := i_uliTotalLengthMm;
    iq_stState.xInitialized := TRUE;
END_IF;


// Заказ может изменить только серверный интерфейс. Сервер пишет параметры,
// затем новый sequence и только после этого команду 16#4F52.
IF i_wServerOrderCommand <> WORD#0 THEN
    q_xServerOrderCommandConsumed := TRUE;

    IF i_wServerOrderSequence <> iq_stPersistent.wLastServerOrderSequence THEN
        iq_stPersistent.wLastServerOrderSequence := i_wServerOrderSequence;
        iq_stState.wLastServerOrderSequence := i_wServerOrderSequence;

        IF i_wServerOrderCommand <> GVL_Constants.c_wServerOrderApplyCommand THEN
            iq_stState.wLastServerOrderResult := WORD#2;
        ELSIF (i_udiServerOrderDatabaseId = UDINT#0)
           OR (i_wServerOrderSourceShift = WORD#0)
           OR (i_wServerChangeoverTenthsMin > WORD#6000) THEN
            iq_stState.wLastServerOrderResult := WORD#3;
        ELSE
            iq_stPersistent.udiOrderDatabaseId := i_udiServerOrderDatabaseId;
            iq_stPersistent.udiOrderTechnicalCard := i_udiServerOrderTechnicalCard;
            iq_stPersistent.udiOrderNumber := i_udiServerOrderNumber;
            iq_stPersistent.uiOrderSourceShift := WORD_TO_UINT(i_wServerOrderSourceShift);
            iq_stPersistent.uiOrderNominalSpeed := WORD_TO_UINT(i_wServerOrderNominalSpeed);
            iq_stPersistent.uiChangeoverSetpointTenthsMin :=
                WORD_TO_UINT(i_wServerChangeoverTenthsMin);
            iq_stPersistent.uliOrderBaselineMm := i_uliTotalLengthMm;

            iq_stState.xPackingComplete := FALSE;
            iq_stState.xServerOrderValid := TRUE;
            iq_stState.wStateCode := GVL_Constants.c_wStopStateChangeover;
            iq_stState.wLastServerOrderResult := WORD#1;
            uliRunDetectBaselineMm := i_uliTotalLengthMm;
        END_IF;
    END_IF;
END_IF;


iq_stState.xConfigFault :=
    (iq_stPersistent.uiAreaCoefficientX100 = UINT#0)
    OR (iq_stPersistent.uiAreaCoefficientX100 > UINT#1000)
    OR (iq_stPersistent.uiStartDetectLengthDm = UINT#0)
    OR (iq_stPersistent.uiStartDetectLengthDm > UINT#6000)
    OR (iq_stPersistent.uiChangeoverSetpointTenthsMin > UINT#6000);


// Сброс аппаратного счётчика не должен создавать отрицательные или огромные дельты.
IF i_uliTotalLengthMm < iq_stPersistent.uliOrderBaselineMm THEN
    iq_stPersistent.uliOrderBaselineMm := i_uliTotalLengthMm;
END_IF;

IF i_uliTotalLengthMm < iq_stPersistent.uliShiftBaselineMm THEN
    iq_stPersistent.uliShiftBaselineMm := i_uliTotalLengthMm;
END_IF;


// Сравнение с постоянным номером смены также ловит смену, прошедшую при
// выключенном PLC, когда однократного xShiftChanged уже не было.
IF ((i_usiCurrentShift = USINT#1) OR (i_usiCurrentShift = USINT#2))
   AND (i_xShiftChanged
        OR (iq_stPersistent.usiLastShiftNumber <> i_usiCurrentShift)) THEN
    iq_stPersistent.uliShiftBaselineMm := i_uliTotalLengthMm;
    iq_stPersistent.usiLastShiftNumber := i_usiCurrentShift;
END_IF;


// Любой ненулевой CommandCode очищается. Действие выполняется только один раз
// при новом sequence, поэтому оставшийся после перезапуска пакет не повторится.
IF i_wCommandCode <> WORD#0 THEN
    q_xCommandConsumed := TRUE;

    IF i_wCommandSequence <> iq_stState.wLastProcessedSequence THEN
        iq_stState.wLastProcessedSequence := i_wCommandSequence;
        iq_stState.wLastCommandResult := GVL_Constants.c_wStopResultAccepted;
        iq_stState.xCommandRejected := FALSE;

        // Причина остановки принимается только при исправном энкодере и
        // отсутствии движения. HMI не может объявить работу без движения.
        IF ((i_wCommandCode = WORD#2)
            AND (NOT i_xMoving OR NOT i_xLineDataValid))
           OR (((i_wCommandCode = WORD#1)
                OR ((i_wCommandCode >= WORD#3) AND (i_wCommandCode <= WORD#10)))
               AND (i_xMoving OR NOT i_xLineDataValid)) THEN
            iq_stState.wLastCommandResult := GVL_Constants.c_wStopResultInvalidState;
            iq_stState.xCommandRejected := TRUE;
        ELSE
        CASE i_wCommandCode OF

        1: // СТОП: меняет только состояние линии в отчёте.
            iq_stState.wStateCode := GVL_Constants.c_wStopStateStopped;
            uliRunDetectBaselineMm := i_uliTotalLengthMm;

        2: // ПУСК: меняет только состояние линии в отчёте.
            iq_stState.wStateCode := GVL_Constants.c_wStopStateRunning;

        3: // ПЕРЕНАЛАДКА. Заказ задаёт только сервер; HMI меняет лишь состояние.
            iq_stState.xPackingComplete := FALSE;
            iq_stState.wStateCode := GVL_Constants.c_wStopStateChangeover;
            uliRunDetectBaselineMm := i_uliTotalLengthMm;

        4: // ПРОИЗВОДСТВО
            iq_stState.wStateCode := GVL_Constants.c_wStopStateProduction;
            uliRunDetectBaselineMm := i_uliTotalLengthMm;

        5: // ОБЕД
            iq_stState.wStateCode := GVL_Constants.c_wStopStateLunch;
            uliRunDetectBaselineMm := i_uliTotalLengthMm;

        6: // ППР
            iq_stState.wStateCode := GVL_Constants.c_wStopStatePpr;
            uliRunDetectBaselineMm := i_uliTotalLengthMm;

        7: // РЕМОНТ
            iq_stState.wStateCode := GVL_Constants.c_wStopStateRepair;
            uliRunDetectBaselineMm := i_uliTotalLengthMm;

        8: // АВАРИЯ
            iq_stState.wStateCode := GVL_Constants.c_wStopStateAlarm;
            uliRunDetectBaselineMm := i_uliTotalLengthMm;

        9: // ТЕХНОЛОГИЯ
            iq_stState.wStateCode := GVL_Constants.c_wStopStateTechnology;
            uliRunDetectBaselineMm := i_uliTotalLengthMm;

        10: // ОБРЫВ: точка 1...5, сторона 1...2, причина 1...3.
            IF (i_wParam0 >= WORD#1) AND (i_wParam0 <= WORD#5)
               AND (i_wParam1 >= WORD#1) AND (i_wParam1 <= WORD#2)
               AND (i_wParam2 >= WORD#1) AND (i_wParam2 <= WORD#3) THEN
                iq_stState.usiLastBreakPoint := WORD_TO_USINT(i_wParam0);
                iq_stState.usiLastBreakSide := WORD_TO_USINT(i_wParam1);
                iq_stState.usiLastBreakReason := WORD_TO_USINT(i_wParam2);
                iq_stState.wStateCode := GVL_Constants.c_wStopStateBreak;
                uliRunDetectBaselineMm := i_uliTotalLengthMm;
                xBreakRecordedPulse := TRUE;
                q_xBreakRecorded := TRUE;
            ELSE
                iq_stState.wLastCommandResult := GVL_Constants.c_wStopResultInvalidParameter;
                iq_stState.xCommandRejected := TRUE;
            END_IF;

        11: // УПАКОВКА ЗАВЕРШЕНА
            iq_stState.xPackingComplete := TRUE;

        12: // НОМЕР ОПЕРАТОРА. Param0=0 выполняет выход пользователя.
            iq_stPersistent.uiOperatorNumber := WORD_TO_UINT(i_wParam0);

        20: // ПРИМЕНИТЬ НАСТРОЙКИ одним атомарным пакетом.
            xSettingsValid :=
                (i_wSettingStartDetectLengthDm >= WORD#1)
                AND (i_wSettingStartDetectLengthDm <= WORD#6000)
                AND (i_wSettingAreaCoefficientX100 >= WORD#1)
                AND (i_wSettingAreaCoefficientX100 <= WORD#1000)
                AND (i_wSettingChangeoverTenthsMin <= WORD#6000);

            IF xSettingsValid THEN
                iq_stPersistent.uiStartDetectLengthDm := WORD_TO_UINT(i_wSettingStartDetectLengthDm);
                iq_stPersistent.uiAreaCoefficientX100 := WORD_TO_UINT(i_wSettingAreaCoefficientX100);
                iq_stPersistent.uiChangeoverSetpointTenthsMin := WORD_TO_UINT(i_wSettingChangeoverTenthsMin);
            ELSE
                iq_stState.wLastCommandResult := GVL_Constants.c_wStopResultInvalidParameter;
                iq_stState.xCommandRejected := TRUE;
            END_IF;

            ELSE
                iq_stState.wLastCommandResult := GVL_Constants.c_wStopResultInvalidCode;
                iq_stState.xCommandRejected := TRUE;

        END_CASE;
        END_IF;
    END_IF;
END_IF;


// Достоверное движение шестого энкодера возвращает статус RUNNING.
// xMoving обновляется раз в секунду; старый порог 50 м здесь не используется.
IF i_xMoving
   AND i_xLineDataValid
   AND NOT iq_stState.xConfigFault
   AND (iq_stState.wStateCode <> GVL_Constants.c_wStopStateRunning) THEN
    iq_stState.wStateCode := GVL_Constants.c_wStopStateRunning;
END_IF;


// Если подтверждённая работа прекратилась, после задержки фиксируем отсутствие подачи.
fbNoFeed(
    IN := ((iq_stState.wStateCode = GVL_Constants.c_wStopStateRunning)
           OR (iq_stState.wStateCode = WORD#0))
          AND i_xLineDataValid
          AND NOT i_xMoving,
    PT := GVL_Constants.c_tStopNoFeedDelay
);

IF fbNoFeed.Q THEN
    iq_stState.wStateCode := GVL_Constants.c_wStopStateNoFeed;
    uliRunDetectBaselineMm := i_uliTotalLengthMm;
END_IF;


// Таймер переналадки. Нулевое задание означает, что контроль времени отключён.
udiChangeoverTimeMs :=
    UINT_TO_UDINT(iq_stPersistent.uiChangeoverSetpointTenthsMin)
    * UDINT#6000;

fbChangeover(
    IN := (iq_stState.wStateCode = GVL_Constants.c_wStopStateChangeover)
          AND (iq_stPersistent.uiChangeoverSetpointTenthsMin > UINT#0),
    PT := UDINT_TO_TIME(udiChangeoverTimeMs)
);

iq_stState.xChangeoverOverdue := fbChangeover.Q;

IF (iq_stState.wStateCode = GVL_Constants.c_wStopStateChangeover)
   AND (iq_stPersistent.uiChangeoverSetpointTenthsMin > UINT#0) THEN
    udiElapsedMs := TIME_TO_UDINT(fbChangeover.ET);
    IF udiElapsedMs < udiChangeoverTimeMs THEN
        udiRemainingMs := udiChangeoverTimeMs - udiElapsedMs;
        iq_stState.uiChangeoverRemainingTenthsMin :=
            UDINT_TO_UINT((udiRemainingMs + UDINT#5999) / UDINT#6000);
    ELSE
        iq_stState.uiChangeoverRemainingTenthsMin := UINT#0;
    END_IF;
ELSE
    iq_stState.uiChangeoverRemainingTenthsMin :=
        iq_stPersistent.uiChangeoverSetpointTenthsMin;
END_IF;


// Расчёт выпуска заказа и смены от независимых базовых отметок.
uliOrderDeltaMm := i_uliTotalLengthMm - iq_stPersistent.uliOrderBaselineMm;
uliShiftDeltaMm := i_uliTotalLengthMm - iq_stPersistent.uliShiftBaselineMm;
uliOrderLengthDm := uliOrderDeltaMm / ULINT#100;
uliShiftLengthDm := uliShiftDeltaMm / ULINT#100;

IF uliOrderLengthDm <= ULINT#4294967295 THEN
    iq_stState.udiCurrentOrderLengthDm := ULINT_TO_UDINT(uliOrderLengthDm);
ELSE
    iq_stState.udiCurrentOrderLengthDm := UDINT#4294967295;
END_IF;

IF uliShiftLengthDm <= ULINT#4294967295 THEN
    iq_stState.udiShiftLengthDm := ULINT_TO_UDINT(uliShiftLengthDm);
ELSE
    iq_stState.udiShiftLengthDm := UDINT#4294967295;
END_IF;

uliOrderAreaX100 :=
    uliOrderLengthDm * UINT_TO_ULINT(iq_stPersistent.uiAreaCoefficientX100) / ULINT#10;
uliShiftAreaX100 :=
    uliShiftLengthDm * UINT_TO_ULINT(iq_stPersistent.uiAreaCoefficientX100) / ULINT#10;

IF uliOrderAreaX100 <= ULINT#4294967295 THEN
    iq_stState.udiCurrentOrderAreaX100 := ULINT_TO_UDINT(uliOrderAreaX100);
ELSE
    iq_stState.udiCurrentOrderAreaX100 := UDINT#4294967295;
END_IF;

IF uliShiftAreaX100 <= ULINT#4294967295 THEN
    iq_stState.udiShiftAreaX100 := ULINT_TO_UDINT(uliShiftAreaX100);
ELSE
    iq_stState.udiShiftAreaX100 := UDINT#4294967295;
END_IF;

iq_stState.udiOrderNumber := iq_stPersistent.udiOrderNumber;
iq_stState.udiOrderDatabaseId := iq_stPersistent.udiOrderDatabaseId;
iq_stState.udiOrderTechnicalCard := iq_stPersistent.udiOrderTechnicalCard;
iq_stState.uiOrderSourceShift := iq_stPersistent.uiOrderSourceShift;
iq_stState.uiOrderNominalSpeed := iq_stPersistent.uiOrderNominalSpeed;
iq_stState.uiOperatorNumber := iq_stPersistent.uiOperatorNumber;

IF i_rSpeedMPerMin <= 0.0 THEN
    iq_stState.uiSpeedDmPerMin := UINT#0;
ELSIF i_rSpeedMPerMin >= 6553.5 THEN
    iq_stState.uiSpeedDmPerMin := UINT#65535;
ELSE
    iq_stState.uiSpeedDmPerMin := REAL_TO_UINT(i_rSpeedMPerMin * 10.0);
END_IF;


// Биты состояния предназначены только для индикации и диагностики HMI.
iq_stState.wStatusBits := WORD#16#0001; // bit 0: блок активен.
IF i_xRtcValid THEN
    iq_stState.wStatusBits := iq_stState.wStatusBits OR WORD#16#0002;
END_IF;
IF i_xMoving THEN
    iq_stState.wStatusBits := iq_stState.wStatusBits OR WORD#16#0004;
END_IF;
IF i_xLineDataValid THEN
    iq_stState.wStatusBits := iq_stState.wStatusBits OR WORD#16#0008;
END_IF;
IF iq_stState.xChangeoverOverdue THEN
    iq_stState.wStatusBits := iq_stState.wStatusBits OR WORD#16#0010;
END_IF;
IF iq_stState.xCommandRejected THEN
    iq_stState.wStatusBits := iq_stState.wStatusBits OR WORD#16#0040;
END_IF;
IF NOT iq_stState.xConfigFault THEN
    iq_stState.wStatusBits := iq_stState.wStatusBits OR WORD#16#0080;
END_IF;
IF xBreakRecordedPulse THEN
    iq_stState.wStatusBits := iq_stState.wStatusBits OR WORD#16#0100;
END_IF;
IF iq_stState.xServerOrderValid THEN
    iq_stState.wStatusBits := iq_stState.wStatusBits OR WORD#16#0200;
END_IF;


iq_stState.wAlarmBits := WORD#0;
IF iq_stState.wStateCode = GVL_Constants.c_wStopStateNoFeed THEN
    iq_stState.wAlarmBits := iq_stState.wAlarmBits OR WORD#16#0001;
END_IF;
IF NOT i_xLineDataValid THEN
    iq_stState.wAlarmBits := iq_stState.wAlarmBits OR WORD#16#0002;
END_IF;
IF iq_stState.xChangeoverOverdue THEN
    iq_stState.wAlarmBits := iq_stState.wAlarmBits OR WORD#16#0004;
END_IF;
IF iq_stState.xCommandRejected THEN
    iq_stState.wAlarmBits := iq_stState.wAlarmBits OR WORD#16#0008;
END_IF;
IF iq_stState.xConfigFault THEN
    iq_stState.wAlarmBits := iq_stState.wAlarmBits OR WORD#16#0010;
END_IF;

InterfaceAsPlainText.html:xhtml:
FUNCTION_BLOCK FB_StopMachine
VAR_INPUT
    i_uliTotalLengthMm               : ULINT; // Общий метраж шестого энкодера.
    i_rSpeedMPerMin                  : REAL;  // Измеренная скорость линии.
    i_xMoving                        : BOOL;  // За последний интервал были импульсы линии.
    i_xLineDataValid                 : BOOL;  // Данные шестого HSC разрешено использовать.
    i_usiCurrentShift                : USINT; // Номер текущей смены 1 или 2.
    i_xShiftChanged                  : BOOL;  // Одноцикловый признак смены.
    i_xRtcValid                      : BOOL;  // Часы ПЛК исправны.
    i_wRestoredState                 : WORD;  // Последняя причина из отдельного постоянного блока.
    i_wCommandCode                   : WORD;  // Код команды HMI.
    i_wCommandSequence               : WORD;  // Новый номер для каждого нажатия.
    i_wParam0                        : WORD;  // Параметр команды 0.
    i_wParam1                        : WORD;  // Параметр команды 1.
    i_wParam2                        : WORD;  // Параметр команды 2.
    i_wSettingStartDetectLengthDm    : WORD;  // Новый порог подтверждения движения, 0,1 м.
    i_wSettingAreaCoefficientX100    : WORD;  // Новый коэффициент площади x 100.
    i_wSettingChangeoverTenthsMin    : WORD;  // Новое время переналадки, 0,1 мин.
    i_wServerOrderCommand            : WORD;  // 16#4F52 применяется после записи всего пакета заказа.
    i_wServerOrderSequence           : WORD;  // Новый номер для каждой записи заказа сервером.
    i_udiServerOrderDatabaseId       : UDINT; // NumZ из базы данных.
    i_udiServerOrderTechnicalCard    : UDINT; // NumTK из базы данных.
    i_udiServerOrderNumber           : UDINT; // Числовая часть Zakaz для отображения.
    i_wServerOrderSourceShift        : WORD;  // NumSM из базы данных.
    i_wServerOrderNominalSpeed       : WORD;  // Efficiency из базы данных.
    i_wServerChangeoverTenthsMin     : WORD;  // ReconfigurationT x 10.
END_VAR

VAR_IN_OUT
    iq_stPersistent : ST_StopMachinePersistent;
    iq_stState      : ST_StopMachineState;
END_VAR

VAR_OUTPUT
    q_xCommandConsumed : BOOL; // PLC принял пакет команды и может очистить CommandCode.
    q_xServerOrderCommandConsumed : BOOL; // PLC обработал/отклонил и может очистить серверную команду.
    q_xBreakRecorded : BOOL; // Приняты подробности обрыва, включая изменение причины в том же состоянии.
END_VAR

VAR
    fbNoFeed                 : TON;
    fbChangeover             : TON;
    uliRunDetectBaselineMm   : ULINT;
    uliOrderDeltaMm          : ULINT;
    uliShiftDeltaMm          : ULINT;
    uliOrderLengthDm         : ULINT;
    uliShiftLengthDm         : ULINT;
    uliOrderAreaX100         : ULINT;
    uliShiftAreaX100         : ULINT;
    udiChangeoverTimeMs      : UDINT;
    udiElapsedMs             : UDINT;
    udiRemainingMs           : UDINT;
    xSettingsValid           : BOOL;
    xBreakRecordedPulse      : BOOL;
END_VAR

ST.html:xhtml:
xTriggerRising := i_xTrigger AND NOT xTriggerPrevious;
xTriggerPrevious := i_xTrigger;


// Каждое новое подтверждённое нажатие начинает три вспышки заново.
IF xTriggerRising THEN
    usiPhase := USINT#1;
    xResetTimer := TRUE;
END_IF;


// После каждой полуволны TON сбрасывается на один цикл программы.
IF xResetTimer THEN
    fbPhaseTimer(
        IN := FALSE,
        PT := i_tHalfPeriod
    );
    xResetTimer := FALSE;
ELSE
    fbPhaseTimer(
        IN := usiPhase <> USINT#0,
        PT := i_tHalfPeriod
    );

    IF fbPhaseTimer.Q THEN
        IF usiPhase >= USINT#6 THEN
            usiPhase := USINT#0;
        ELSE
            usiPhase := usiPhase + USINT#1;
        END_IF;
        xResetTimer := TRUE;
    END_IF;
END_IF;


q_xActive := usiPhase <> USINT#0;
q_xFlashOn :=
    (usiPhase = USINT#1)
    OR (usiPhase = USINT#3)
    OR (usiPhase = USINT#5);

// ============================================================
// 0. Контроль разметки постоянной памяти
// ============================================================

// При первом запуске этой версии старая PERSISTENT-разметка может содержать
// данные прежнего проекта в новых полях. Несовпадение сигнатуры или версии
// очищает только данные приложения, после чего признак сохраняется.
IF (PersistentVars.dwLayoutSignature <> GVL_Constants.c_dwPersistentLayoutSignature)
   OR (PersistentVars.wLayoutVersion <> GVL_Constants.c_wPersistentLayoutVersion) THEN

    FOR iPersistentEvent := 0 TO 127 DO
        PersistentVars.a_stEventQueue[iPersistentEvent] := stEmptyRollEvent;
    END_FOR;

    FOR iPersistentRoll := 1 TO GVL_Constants.c_iRollChannelCount DO
        PersistentVars.a_stRollState[iPersistentRoll] := stEmptyRollState;
        PersistentVars.a_uliShiftRollPulses[iPersistentRoll] := ULINT#0;
    END_FOR;

    PersistentVars.uiEventQueueHead := UINT#0;
    PersistentVars.uiEventQueueTail := UINT#0;
    PersistentVars.uiEventQueueCount := UINT#0;
    PersistentVars.udiNextEventId := UDINT#1;
    PersistentVars.udiQueueOverflowCount := UDINT#0;
    PersistentVars.stStopMachine := stEmptyStopMachine;
    PersistentVars.usiShiftAccumulatorNumber := USINT#0;
    PersistentVars.udiShiftStartTimestampUtc := UDINT#0;
    PersistentVars.uliShiftOutputPulses := ULINT#0;
    PersistentVars.dwLayoutSignature := GVL_Constants.c_dwPersistentLayoutSignature;
    PersistentVars.wLayoutVersion := GVL_Constants.c_wPersistentLayoutVersion;

END_IF;

// Новый журнал имеет собственную persistent-разметку и не сбрасывает
// существующие счётчики рулонов при первом импорте.
IF PersistentVars.stStopJournal.dwSignature <> DWORD#16#534A4C34 THEN
    FOR iStopJournalPersistentIndex := 0 TO 127 DO
        PersistentVars.stStopJournal.a_stQueue[iStopJournalPersistentIndex] := stEmptyStopJournalEvent;
    END_FOR;
    PersistentVars.stStopJournal.uiHead := UINT#0;
    PersistentVars.stStopJournal.uiTail := UINT#0;
    PersistentVars.stStopJournal.uiCount := UINT#0;
    PersistentVars.stStopJournal.udiNextEventId := UDINT#1;
    PersistentVars.stStopJournal.udiOverflowCount := UDINT#0;
    PersistentVars.stStopJournal.uliLinePulses := ULINT#0;
    PersistentVars.stStopJournal.wLastState := WORD#0;
    PersistentVars.stStopJournal.dwSignature := DWORD#16#534A4C34;
END_IF;

// ============================================================
// 1. Вызов шести аппаратных HSC
// ============================================================

HscSimple_0(
    Enable := TRUE,
    Sync := xHscFirstCycle,
    ACK_Modulo := FALSE,
    HSC_Err => GVL_IO.xHscError[1],
    Validity => GVL_IO.xHscValid[1],
    CurrentValue => a_dwHscRaw[1]
);

HscSimple_1(
    Enable := TRUE,
    Sync := xHscFirstCycle,
    ACK_Modulo := FALSE,
    HSC_Err => GVL_IO.xHscError[2],
    Validity => GVL_IO.xHscValid[2],
    CurrentValue => a_dwHscRaw[2]
);

HscSimple_2(
    Enable := TRUE,
    Sync := xHscFirstCycle,
    ACK_Modulo := FALSE,
    HSC_Err => GVL_IO.xHscError[3],
    Validity => GVL_IO.xHscValid[3],
    CurrentValue => a_dwHscRaw[3]
);

HscSimple_3(
    Enable := TRUE,
    Sync := xHscFirstCycle,
    ACK_Modulo := FALSE,
    HSC_Err => GVL_IO.xHscError[4],
    Validity => GVL_IO.xHscValid[4],
    CurrentValue => a_dwHscRaw[4]
);

HscSimple_4(
    Enable := TRUE,
    Sync := xHscFirstCycle,
    ACK_Modulo := FALSE,
    HSC_Err => GVL_IO.xHscError[5],
    Validity => GVL_IO.xHscValid[5],
    CurrentValue => a_dwHscRaw[5]
);

HscSimple_5(
    Enable := TRUE,
    Sync := xHscFirstCycle,
    ACK_Modulo := FALSE,
    HSC_Err => GVL_IO.xHscError[6],
    Validity => GVL_IO.xHscValid[6],
    CurrentValue => a_dwHscRaw[6]
);


// Sync активен только при первом проходе SR_Main.
xHscFirstCycle := FALSE;


// ============================================================
// 2. Обработка абсолютных значений HSC
// ============================================================

GVL_Diagnostics.stSystem.xAnyHscFault := FALSE;
GVL_Diagnostics.stSystem.xAnyConfigFault := FALSE;


FOR iHsc := 1 TO GVL_Constants.c_iHscChannelCount DO

    GVL_IO.udiHscAbs[iHsc] :=
        DWORD_TO_UDINT(a_dwHscRaw[iHsc]);


    a_fbHscTracker[iHsc](
        i_udiHscAbs := GVL_IO.udiHscAbs[iHsc],
        i_xHscValid := GVL_IO.xHscValid[iHsc],
        i_xHscError := GVL_IO.xHscError[iHsc],
        i_udiCounterRange := GVL_Constants.c_udiHscCounterRange,
        i_udiMaxDeltaPerCycle := GVL_Constants.c_udiMaxPulseDeltaPerCycle,
        iq_stState := GVL_Runtime.a_stHscState[iHsc]
    );


    GVL_Diagnostics.stSystem.a_eHscStatus[iHsc] :=
        GVL_Runtime.a_stHscState[iHsc].eStatus;

    GVL_Diagnostics.stSystem.a_xHscFault[iHsc] :=
        (GVL_Runtime.a_stHscState[iHsc].eStatus <> CHANNEL_STATUS_RUNNING)
        AND
        (GVL_Runtime.a_stHscState[iHsc].eStatus <> CHANNEL_STATUS_STARTING);

    GVL_Diagnostics.stSystem.xAnyHscFault :=
        GVL_Diagnostics.stSystem.xAnyHscFault
        OR GVL_Diagnostics.stSystem.a_xHscFault[iHsc];

    GVL_Diagnostics.stSystem.xAnyConfigFault :=
        GVL_Diagnostics.stSystem.xAnyConfigFault
        OR
        (GVL_Runtime.a_stHscState[iHsc].eStatus = CHANNEL_STATUS_CONFIG_ERROR);

END_FOR;


// ============================================================
// 3. Определение номера текущей смены и времени события
// ============================================================

fbShiftManager(
    i_usiShift1StartHour := GVL_Constants.c_usiShift_1_StartHour,
    i_usiShift2StartHour := GVL_Constants.c_usiShift_2_StartHour,
    i_udiUtcOffsetSeconds := GVL_Constants.c_udiLocalUtcOffsetSeconds,
    iq_stState := GVL_Runtime.stShiftState
);


GVL_Diagnostics.stSystem.xRtcFault :=
    NOT GVL_Runtime.stShiftState.xRtcValid;


// Общая часть пакета всех DWIN. Компоненты времени передаются отдельными
// 16-битными числами, поэтому панели не зависят от порядка слов UDINT.
a_wDwinCommon[5] := UINT_TO_WORD(GVL_Runtime.stShiftState.uiLocalYear);
a_wDwinCommon[6] := UINT_TO_WORD(GVL_Runtime.stShiftState.uiLocalMonth);
a_wDwinCommon[7] := UINT_TO_WORD(GVL_Runtime.stShiftState.uiLocalDay);
a_wDwinCommon[8] := UINT_TO_WORD(GVL_Runtime.stShiftState.uiLocalHour);
a_wDwinCommon[9] := UINT_TO_WORD(GVL_Runtime.stShiftState.uiLocalMinute);
a_wDwinCommon[10] := UINT_TO_WORD(GVL_Runtime.stShiftState.uiLocalSecond);
a_wDwinCommon[11] := USINT_TO_WORD(GVL_Runtime.stShiftState.usiCurrentShift);
IF GVL_Runtime.stShiftState.xRtcValid THEN
    a_wDwinCommon[12] := WORD#1;
ELSE
    a_wDwinCommon[12] := WORD#0;
END_IF;


// Системный RTC DWIN устанавливается записью четырёх слов с VP 009C:
// 5AA5, YYMM, DDHH, MMSS. Год передаётся смещением от 2000.
IF GVL_Runtime.stShiftState.xRtcValid
   AND (GVL_Runtime.stShiftState.uiLocalYear >= UINT#2000)
   AND (GVL_Runtime.stShiftState.uiLocalYear <= UINT#2255)
   AND (GVL_Runtime.stShiftState.uiLocalMonth >= UINT#1)
   AND (GVL_Runtime.stShiftState.uiLocalMonth <= UINT#12)
   AND (GVL_Runtime.stShiftState.uiLocalDay >= UINT#1)
   AND (GVL_Runtime.stShiftState.uiLocalDay <= UINT#31)
   AND (GVL_Runtime.stShiftState.uiLocalHour <= UINT#23)
   AND (GVL_Runtime.stShiftState.uiLocalMinute <= UINT#59)
   AND (GVL_Runtime.stShiftState.uiLocalSecond <= UINT#59) THEN

    a_wDwinRtcCommon[0] := WORD#16#5AA5;
    a_wDwinRtcCommon[1] :=
        SHL(
            UINT_TO_WORD(GVL_Runtime.stShiftState.uiLocalYear - UINT#2000),
            8
        )
        OR UINT_TO_WORD(GVL_Runtime.stShiftState.uiLocalMonth);
    a_wDwinRtcCommon[2] :=
        SHL(UINT_TO_WORD(GVL_Runtime.stShiftState.uiLocalDay), 8)
        OR UINT_TO_WORD(GVL_Runtime.stShiftState.uiLocalHour);
    a_wDwinRtcCommon[3] :=
        SHL(UINT_TO_WORD(GVL_Runtime.stShiftState.uiLocalMinute), 8)
        OR UINT_TO_WORD(GVL_Runtime.stShiftState.uiLocalSecond);

ELSE

    // Нулевая сигнатура запрещает установку DWIN по недостоверному времени.
    a_wDwinRtcCommon[0] := WORD#0;
    a_wDwinRtcCommon[1] := WORD#0;
    a_wDwinRtcCommon[2] := WORD#0;
    a_wDwinRtcCommon[3] := WORD#0;

END_IF;


FOR iDwinWord := 0 TO 3 DO
    GVL_HMI.a_wHmi1RtcSync[iDwinWord] := a_wDwinRtcCommon[iDwinWord];
    GVL_HMI.a_wHmi2RtcSync[iDwinWord] := a_wDwinRtcCommon[iDwinWord];
    GVL_HMI.a_wHmi3RtcSync[iDwinWord] := a_wDwinRtcCommon[iDwinWord];
    GVL_HMI.a_wHmi4RtcSync[iDwinWord] := a_wDwinRtcCommon[iDwinWord];
    GVL_HMI.a_wHmi5RtcSync[iDwinWord] := a_wDwinRtcCommon[iDwinWord];
END_FOR;


// Накопители смены не зависят от сбросов отдельных рулонов. Они используют
// те же проверенные приращения HSC и сохраняются при перезапуске ПЛК.
IF GVL_Runtime.stShiftState.xRtcValid THEN

    xShiftIntervalExpired := FALSE;
    IF PersistentVars.udiShiftStartTimestampUtc <> UDINT#0 THEN
        IF GVL_Runtime.stShiftState.udiTimestampUtc
           < PersistentVars.udiShiftStartTimestampUtc THEN
            xShiftIntervalExpired := TRUE;
        ELSE
            xShiftIntervalExpired :=
                (GVL_Runtime.stShiftState.udiTimestampUtc
                 - PersistentVars.udiShiftStartTimestampUtc)
                >= GVL_Constants.c_udiShiftMaxIntervalSeconds;
        END_IF;
    END_IF;

    IF (PersistentVars.usiShiftAccumulatorNumber < USINT#1)
       OR (PersistentVars.usiShiftAccumulatorNumber > USINT#2)
       OR (PersistentVars.usiShiftAccumulatorNumber <> GVL_Runtime.stShiftState.usiCurrentShift)
       OR (PersistentVars.udiShiftStartTimestampUtc = UDINT#0)
       OR xShiftIntervalExpired THEN

        PersistentVars.usiShiftAccumulatorNumber :=
            GVL_Runtime.stShiftState.usiCurrentShift;
        PersistentVars.udiShiftStartTimestampUtc :=
            GVL_Runtime.stShiftState.udiTimestampUtc;
        PersistentVars.uliShiftOutputPulses := ULINT#0;

        FOR iRoll := 1 TO GVL_Constants.c_iRollChannelCount DO
            PersistentVars.a_uliShiftRollPulses[iRoll] := ULINT#0;
        END_FOR;

    END_IF;

    FOR iRoll := 1 TO GVL_Constants.c_iRollChannelCount DO
        IF GVL_Runtime.a_stHscState[iRoll].xDataValid THEN
            IF PersistentVars.a_uliShiftRollPulses[iRoll]
               <= (ULINT#18446744073709551615
                   - UDINT_TO_ULINT(GVL_Runtime.a_stHscState[iRoll].udiPulseDelta)) THEN
                PersistentVars.a_uliShiftRollPulses[iRoll] :=
                    PersistentVars.a_uliShiftRollPulses[iRoll]
                    + UDINT_TO_ULINT(GVL_Runtime.a_stHscState[iRoll].udiPulseDelta);
            ELSE
                PersistentVars.a_uliShiftRollPulses[iRoll] :=
                    ULINT#18446744073709551615;
                GVL_Diagnostics.stSystem.xAnyConfigFault := TRUE;
            END_IF;
        END_IF;
    END_FOR;

    IF GVL_Runtime.a_stHscState[6].xDataValid THEN
        IF PersistentVars.uliShiftOutputPulses
           <= (ULINT#18446744073709551615
               - UDINT_TO_ULINT(GVL_Runtime.a_stHscState[6].udiPulseDelta)) THEN
            PersistentVars.uliShiftOutputPulses :=
                PersistentVars.uliShiftOutputPulses
                + UDINT_TO_ULINT(GVL_Runtime.a_stHscState[6].udiPulseDelta);
        ELSE
            PersistentVars.uliShiftOutputPulses := ULINT#18446744073709551615;
            GVL_Diagnostics.stSystem.xAnyConfigFault := TRUE;
        END_IF;
    END_IF;

END_IF;


// ============================================================
// 4. Фильтрация кнопок и учёт пяти раскатов
// ============================================================

FOR iRoll := 1 TO GVL_Constants.c_iRollChannelCount DO

    a_fbSpliceFilter[iRoll](
        i_xRaw := GVL_IO.xSplice[iRoll],
        i_tOnDelay := GVL_Constants.c_tInputFilter
    );

    a_fbResetFilter[iRoll](
        i_xRaw := GVL_IO.xReset[iRoll],
        i_tOnDelay := GVL_Constants.c_tInputFilter
    );


    a_fbRollCounter[iRoll](
        i_udiPulseDelta := GVL_Runtime.a_stHscState[iRoll].udiPulseDelta,
        i_xPulseDataValid := GVL_Runtime.a_stHscState[iRoll].xDataValid,
        i_xSplice := a_fbSpliceFilter[iRoll].q_xFiltered,
        i_xReset := a_fbResetFilter[iRoll].q_xFiltered,
        i_udiPulsesPerRevolution := GVL_Constants.c_udiEncoderPulsesPerRevolution,
        i_udiWheelCircumferenceMm := GVL_Constants.c_udiWheelCircumferenceMm,
        i_uliManualResetMinLengthMm := GVL_Constants.c_uliManualResetMinLengthMm,
        iq_stState := PersistentVars.a_stRollState[iRoll]
    );


    GVL_Diagnostics.stSystem.xAnyConfigFault :=
        GVL_Diagnostics.stSystem.xAnyConfigFault
        OR PersistentVars.a_stRollState[iRoll].xConfigFault;


    // При завершении рулона создаём неизменяемый снимок для постоянной очереди.
    a_xRollEventRequest[iRoll] :=
        PersistentVars.a_stRollState[iRoll].xRollCompleted;


    // Одноцикловые признаки преобразуем в устойчивые состояния для HMI,
    // которая опрашивает Modbus значительно медленнее цикла программы ПЛК.
    xRollPulseThisCycle :=
        GVL_Runtime.a_stHscState[iRoll].xDataValid
        AND (GVL_Runtime.a_stHscState[iRoll].udiPulseDelta > UDINT#0);

    IF xRollPulseThisCycle THEN
        a_xHaiwellActivitySeen[iRoll] := TRUE;
    END_IF;

    a_fbHaiwellActivityTimeout[iRoll](
        IN := NOT xRollPulseThisCycle,
        PT := GVL_Constants.c_tHaiwellActivityHold
    );

    IF a_fbHaiwellActivityTimeout[iRoll].Q THEN
        a_xHaiwellActivitySeen[iRoll] := FALSE;
    END_IF;

    xRollResetThisCycle :=
        (
            PersistentVars.a_stRollState[iRoll].xShortResetDiscarded
            OR
            (
                PersistentVars.a_stRollState[iRoll].xRollCompleted
                AND (PersistentVars.a_stRollState[iRoll].eLastEndReason = ROLL_END_RESET)
            )
        );

    IF xRollResetThisCycle THEN
        a_xHaiwellResetSeen[iRoll] := TRUE;
    END_IF;

    a_fbHaiwellResetTimeout[iRoll](
        IN := NOT xRollResetThisCycle,
        PT := GVL_Constants.c_tHaiwellResetHold
    );

    IF a_fbHaiwellResetTimeout[iRoll].Q THEN
        a_xHaiwellResetSeen[iRoll] := FALSE;
    END_IF;

    a_fbHaiwellAttentionFlash[iRoll](
        i_xTrigger := a_fbSpliceFilter[iRoll].q_xFiltered
                      OR a_fbResetFilter[iRoll].q_xFiltered,
        i_tHalfPeriod := GVL_Constants.c_tHaiwellFlashHalfPeriod
    );

    IF a_xRollEventRequest[iRoll] THEN
        a_stRollEventRequest[iRoll].udiEventId := UDINT#0; // Настоящий EventId назначит очередь.
        a_stRollEventRequest[iRoll].udiTimestampUtc := GVL_Runtime.stShiftState.udiTimestampUtc;
        a_stRollEventRequest[iRoll].usiUnwindNumber := INT_TO_USINT(iRoll);
        a_stRollEventRequest[iRoll].usiShiftNumber := GVL_Runtime.stShiftState.usiCurrentShift;
        a_stRollEventRequest[iRoll].eEndReason := PersistentVars.a_stRollState[iRoll].eLastEndReason;

        // Физически недостижимый предел защищает явное преобразование ULINT -> UDINT.
        IF PersistentVars.a_stRollState[iRoll].uliPreviousRollLengthMm <= ULINT#4294967295 THEN
            a_stRollEventRequest[iRoll].udiLengthMm :=
                ULINT_TO_UDINT(PersistentVars.a_stRollState[iRoll].uliPreviousRollLengthMm);
        ELSE
            a_stRollEventRequest[iRoll].udiLengthMm := UDINT#4294967295;
            GVL_Diagnostics.stSystem.xAnyConfigFault := TRUE;
        END_IF;
    END_IF;


    // Подготавливаем индивидуальную часть пакета VP 2000...2004 для своей панели.
    a_fbDwinDataPacker[iRoll](
        i_uliCurrentLengthMm := PersistentVars.a_stRollState[iRoll].uliCurrentLengthMm,
        i_uliPreviousLengthMm := PersistentVars.a_stRollState[iRoll].uliPreviousRollLengthMm,
        i_usiUnwindNumber := INT_TO_USINT(iRoll)
    );


    GVL_Diagnostics.stSystem.a_xHmiOverflow[iRoll] :=
        a_fbDwinDataPacker[iRoll].q_xOverflow;


    // Каждая панель имеет собственный массив, удобный для I/O Mapping.
    CASE iRoll OF

        1:
            GVL_HMI.a_wHmi1Tx[0] := a_fbDwinDataPacker[iRoll].q_wCurrentHigh;
            GVL_HMI.a_wHmi1Tx[1] := a_fbDwinDataPacker[iRoll].q_wCurrentLow;
            GVL_HMI.a_wHmi1Tx[2] := a_fbDwinDataPacker[iRoll].q_wPreviousHigh;
            GVL_HMI.a_wHmi1Tx[3] := a_fbDwinDataPacker[iRoll].q_wPreviousLow;
            GVL_HMI.a_wHmi1Tx[4] := a_fbDwinDataPacker[iRoll].q_wUnwindNumber;
            FOR iDwinWord := 5 TO 12 DO
                GVL_HMI.a_wHmi1Tx[iDwinWord] := a_wDwinCommon[iDwinWord];
            END_FOR;

        2:
            GVL_HMI.a_wHmi2Tx[0] := a_fbDwinDataPacker[iRoll].q_wCurrentHigh;
            GVL_HMI.a_wHmi2Tx[1] := a_fbDwinDataPacker[iRoll].q_wCurrentLow;
            GVL_HMI.a_wHmi2Tx[2] := a_fbDwinDataPacker[iRoll].q_wPreviousHigh;
            GVL_HMI.a_wHmi2Tx[3] := a_fbDwinDataPacker[iRoll].q_wPreviousLow;
            GVL_HMI.a_wHmi2Tx[4] := a_fbDwinDataPacker[iRoll].q_wUnwindNumber;
            FOR iDwinWord := 5 TO 12 DO
                GVL_HMI.a_wHmi2Tx[iDwinWord] := a_wDwinCommon[iDwinWord];
            END_FOR;

        3:
            GVL_HMI.a_wHmi3Tx[0] := a_fbDwinDataPacker[iRoll].q_wCurrentHigh;
            GVL_HMI.a_wHmi3Tx[1] := a_fbDwinDataPacker[iRoll].q_wCurrentLow;
            GVL_HMI.a_wHmi3Tx[2] := a_fbDwinDataPacker[iRoll].q_wPreviousHigh;
            GVL_HMI.a_wHmi3Tx[3] := a_fbDwinDataPacker[iRoll].q_wPreviousLow;
            GVL_HMI.a_wHmi3Tx[4] := a_fbDwinDataPacker[iRoll].q_wUnwindNumber;
            FOR iDwinWord := 5 TO 12 DO
                GVL_HMI.a_wHmi3Tx[iDwinWord] := a_wDwinCommon[iDwinWord];
            END_FOR;

        4:
            GVL_HMI.a_wHmi4Tx[0] := a_fbDwinDataPacker[iRoll].q_wCurrentHigh;
            GVL_HMI.a_wHmi4Tx[1] := a_fbDwinDataPacker[iRoll].q_wCurrentLow;
            GVL_HMI.a_wHmi4Tx[2] := a_fbDwinDataPacker[iRoll].q_wPreviousHigh;
            GVL_HMI.a_wHmi4Tx[3] := a_fbDwinDataPacker[iRoll].q_wPreviousLow;
            GVL_HMI.a_wHmi4Tx[4] := a_fbDwinDataPacker[iRoll].q_wUnwindNumber;
            FOR iDwinWord := 5 TO 12 DO
                GVL_HMI.a_wHmi4Tx[iDwinWord] := a_wDwinCommon[iDwinWord];
            END_FOR;

        5:
            GVL_HMI.a_wHmi5Tx[0] := a_fbDwinDataPacker[iRoll].q_wCurrentHigh;
            GVL_HMI.a_wHmi5Tx[1] := a_fbDwinDataPacker[iRoll].q_wCurrentLow;
            GVL_HMI.a_wHmi5Tx[2] := a_fbDwinDataPacker[iRoll].q_wPreviousHigh;
            GVL_HMI.a_wHmi5Tx[3] := a_fbDwinDataPacker[iRoll].q_wPreviousLow;
            GVL_HMI.a_wHmi5Tx[4] := a_fbDwinDataPacker[iRoll].q_wUnwindNumber;
            FOR iDwinWord := 5 TO 12 DO
                GVL_HMI.a_wHmi5Tx[iDwinWord] := a_wDwinCommon[iDwinWord];
            END_FOR;

    END_CASE;

END_FOR;


// ============================================================
// 5. Постоянная очередь событий и подтверждение сервера
// ============================================================

// Сервер передаёт EventId двумя 16-битными словами, старшее слово первым.
udiAckEventId :=
    WORD_TO_UDINT(GVL_SCADA.a_wAckEventId[0]) * UDINT#65536
    + WORD_TO_UDINT(GVL_SCADA.a_wAckEventId[1]);


fbRollEventQueue(
    i_a_xEnqueue := a_xRollEventRequest,
    i_a_stEvent := a_stRollEventRequest,
    i_udiAckEventId := udiAckEventId,
    i_wAckCommand := GVL_SCADA.wAckCommand,
    iq_a_stQueue := PersistentVars.a_stEventQueue,
    iq_uiQueueHead := PersistentVars.uiEventQueueHead,
    iq_uiQueueTail := PersistentVars.uiEventQueueTail,
    iq_uiQueueCount := PersistentVars.uiEventQueueCount,
    iq_udiNextEventId := PersistentVars.udiNextEventId,
    iq_udiOverflowCount := PersistentVars.udiQueueOverflowCount
);


// Команда одноразовая: после обработки ПЛК очищает её сам.
IF fbRollEventQueue.q_xAckCommandConsumed THEN
    GVL_SCADA.wAckCommand := WORD#0;
END_IF;


// Результат последнего подтверждения сохраняется для диагностики.
IF fbRollEventQueue.q_xAckAccepted THEN
    GVL_SCADA.wLastAckResult := WORD#1;
ELSIF fbRollEventQueue.q_xAckRejected THEN
    GVL_SCADA.wLastAckResult := WORD#2;
END_IF;


// Первое неподтверждённое событие остаётся неизменным до правильного ACK.
fbEventPacker(
    i_xEventValid := fbRollEventQueue.q_xEventReady,
    i_stEvent := fbRollEventQueue.q_stCurrentEvent
);

FOR iPacketWord := 0 TO 11 DO
    GVL_SCADA.a_wEventPacket[iPacketWord] :=
        fbEventPacker.q_a_wPacket[iPacketWord];
END_FOR;


IF fbEventPacker.q_xPacketValid THEN
    GVL_SCADA.wEventReady := WORD#1;
ELSE
    GVL_SCADA.wEventReady := WORD#0;
END_IF;

GVL_SCADA.wQueueCount := UINT_TO_WORD(fbRollEventQueue.q_uiQueueCount);
GVL_SCADA.wQueueCapacity := WORD#128;

GVL_SCADA.a_wQueueOverflowCount[0] :=
    UDINT_TO_WORD(PersistentVars.udiQueueOverflowCount / UDINT#65536);
GVL_SCADA.a_wQueueOverflowCount[1] :=
    UDINT_TO_WORD(PersistentVars.udiQueueOverflowCount MOD UDINT#65536);


IF fbRollEventQueue.q_xStorageFault THEN
    GVL_SCADA.wQueueStatus := WORD#3;
ELSIF fbRollEventQueue.q_xEventIdExhausted THEN
    GVL_SCADA.wQueueStatus := WORD#4;
ELSIF fbRollEventQueue.q_xQueueFull THEN
    GVL_SCADA.wQueueStatus := WORD#2;
ELSIF fbRollEventQueue.q_xEventReady THEN
    GVL_SCADA.wQueueStatus := WORD#1;
ELSE
    GVL_SCADA.wQueueStatus := WORD#0;
END_IF;


// ============================================================
// 6. Шестой энкодер: скорость и общий метраж линии
// ============================================================

IF xStopJournalFirstCycle THEN
    GVL_Runtime.stLineState.uliTotalPulses := PersistentVars.stStopJournal.uliLinePulses;
END_IF;

fbLineMeter(
    i_udiPulseDelta := GVL_Runtime.a_stHscState[6].udiPulseDelta,
    i_xPulseDataValid := GVL_Runtime.a_stHscState[6].xDataValid,
    i_udiPulsesPerRevolution := GVL_Constants.c_udiEncoderPulsesPerRevolution,
    i_udiWheelCircumferenceMm := GVL_Constants.c_udiWheelCircumferenceMm,
    i_tSpeedSample := GVL_Constants.c_tSpeedSample,
    iq_stState := GVL_Runtime.stLineState
);

PersistentVars.stStopJournal.uliLinePulses := GVL_Runtime.stLineState.uliTotalPulses;


GVL_Diagnostics.stSystem.xAnyConfigFault :=
    GVL_Diagnostics.stSystem.xAnyConfigFault
    OR GVL_Runtime.stLineState.xConfigFault;


// ============================================================
// 7. Изолированный интерфейс Стопмашины линии ЛГК
// ============================================================

// Все 32-битные поля сервер передаёт старшим словом вперёд.
udiServerOrderDatabaseId :=
    WORD_TO_UDINT(GVL_SCADA.a_wOrderDatabaseId[0]) * UDINT#65536
    + WORD_TO_UDINT(GVL_SCADA.a_wOrderDatabaseId[1]);

udiServerOrderTechnicalCard :=
    WORD_TO_UDINT(GVL_SCADA.a_wOrderTechnicalCard[0]) * UDINT#65536
    + WORD_TO_UDINT(GVL_SCADA.a_wOrderTechnicalCard[1]);

udiServerOrderNumber :=
    WORD_TO_UDINT(GVL_SCADA.a_wOrderDisplayNumber[0]) * UDINT#65536
    + WORD_TO_UDINT(GVL_SCADA.a_wOrderDisplayNumber[1]);

stStopBeforeUpdate := GVL_Runtime.stStopMachine;

fbStopMachine(
    i_uliTotalLengthMm := GVL_Runtime.stLineState.uliTotalLengthMm,
    i_rSpeedMPerMin := GVL_Runtime.stLineState.rSpeedMPerMin,
    i_xMoving := GVL_Runtime.stLineState.xMoving,
    i_xLineDataValid := GVL_Runtime.a_stHscState[6].xDataValid
                        AND NOT GVL_Runtime.stLineState.xConfigFault,
    i_usiCurrentShift := GVL_Runtime.stShiftState.usiCurrentShift,
    i_xShiftChanged := GVL_Runtime.stShiftState.xShiftChanged,
    i_xRtcValid := GVL_Runtime.stShiftState.xRtcValid,
    i_wRestoredState := PersistentVars.stStopJournal.wLastState,
    i_wCommandCode := GVL_StopMachine.wCommandCode,
    i_wCommandSequence := GVL_StopMachine.wCommandSequence,
    i_wParam0 := GVL_StopMachine.wCommandParam0,
    i_wParam1 := GVL_StopMachine.wCommandParam1,
    i_wParam2 := GVL_StopMachine.wCommandParam2,
    i_wSettingStartDetectLengthDm := GVL_StopMachine.wSettingStartDetectLengthDm,
    i_wSettingAreaCoefficientX100 := GVL_StopMachine.wSettingAreaCoefficientX100,
    i_wSettingChangeoverTenthsMin := GVL_StopMachine.wSettingChangeoverTenthsMin,
    i_wServerOrderCommand := GVL_SCADA.wOrderCommand,
    i_wServerOrderSequence := GVL_SCADA.wOrderSequence,
    i_udiServerOrderDatabaseId := udiServerOrderDatabaseId,
    i_udiServerOrderTechnicalCard := udiServerOrderTechnicalCard,
    i_udiServerOrderNumber := udiServerOrderNumber,
    i_wServerOrderSourceShift := GVL_SCADA.wOrderSourceShift,
    i_wServerOrderNominalSpeed := GVL_SCADA.wOrderNominalSpeed,
    i_wServerChangeoverTenthsMin := GVL_SCADA.wOrderChangeoverTenthsMin,
    iq_stPersistent := PersistentVars.stStopMachine,
    iq_stState := GVL_Runtime.stStopMachine
);


// Команда одноразовая. Все параметры HMI записывает до CommandCode.
IF fbStopMachine.q_xCommandConsumed THEN
    GVL_StopMachine.wCommandCode := WORD#0;
END_IF;

// Серверная команда также одноразовая и очищается независимо от результата.
IF fbStopMachine.q_xServerOrderCommandConsumed THEN
    GVL_SCADA.wOrderCommand := WORD#0;
END_IF;

GVL_SCADA.wOrderApplyResult := GVL_Runtime.stStopMachine.wLastServerOrderResult;
GVL_SCADA.wLastOrderSequence := GVL_Runtime.stStopMachine.wLastServerOrderSequence;


// PLC heartbeat изменяется раз в секунду и позволяет HMI обнаружить обрыв связи.
fbInterfaceHeartbeat(
    IN := NOT fbInterfaceHeartbeat.Q,
    PT := T#1s
);

IF fbInterfaceHeartbeat.Q THEN
    IF WORD_TO_UINT(GVL_StopMachine.wPlcHeartbeat) < UINT#65535 THEN
        GVL_StopMachine.wPlcHeartbeat :=
            UINT_TO_WORD(WORD_TO_UINT(GVL_StopMachine.wPlcHeartbeat) + UINT#1);
    ELSE
        GVL_StopMachine.wPlcHeartbeat := WORD#0;
    END_IF;
END_IF;


GVL_StopMachine.wSignature := GVL_Constants.c_wStopMachineSignature;
GVL_StopMachine.wProtocolVersion := GVL_Constants.c_wStopMachineProtocolVersion;
GVL_StopMachine.wStateCode := GVL_Runtime.stStopMachine.wStateCode;
GVL_StopMachine.wStatusBits := GVL_Runtime.stStopMachine.wStatusBits;
GVL_StopMachine.wAlarmBits := GVL_Runtime.stStopMachine.wAlarmBits;
GVL_StopMachine.wShiftNumber := USINT_TO_WORD(GVL_Runtime.stShiftState.usiCurrentShift);
GVL_StopMachine.wLocalHour := UINT_TO_WORD(GVL_Runtime.stShiftState.uiLocalHour);
GVL_StopMachine.wLocalMinute := UINT_TO_WORD(GVL_Runtime.stShiftState.uiLocalMinute);
GVL_StopMachine.wLocalSecond := UINT_TO_WORD(GVL_Runtime.stShiftState.uiLocalSecond);

GVL_StopMachine.a_wOrderNumber[0] :=
    UDINT_TO_WORD(GVL_Runtime.stStopMachine.udiOrderNumber / UDINT#65536);
GVL_StopMachine.a_wOrderNumber[1] :=
    UDINT_TO_WORD(GVL_Runtime.stStopMachine.udiOrderNumber MOD UDINT#65536);

GVL_StopMachine.a_wOrderLengthDm[0] :=
    UDINT_TO_WORD(GVL_Runtime.stStopMachine.udiCurrentOrderLengthDm / UDINT#65536);
GVL_StopMachine.a_wOrderLengthDm[1] :=
    UDINT_TO_WORD(GVL_Runtime.stStopMachine.udiCurrentOrderLengthDm MOD UDINT#65536);

GVL_StopMachine.a_wOrderAreaX100[0] :=
    UDINT_TO_WORD(GVL_Runtime.stStopMachine.udiCurrentOrderAreaX100 / UDINT#65536);
GVL_StopMachine.a_wOrderAreaX100[1] :=
    UDINT_TO_WORD(GVL_Runtime.stStopMachine.udiCurrentOrderAreaX100 MOD UDINT#65536);

GVL_StopMachine.a_wShiftLengthDm[0] :=
    UDINT_TO_WORD(GVL_Runtime.stStopMachine.udiShiftLengthDm / UDINT#65536);
GVL_StopMachine.a_wShiftLengthDm[1] :=
    UDINT_TO_WORD(GVL_Runtime.stStopMachine.udiShiftLengthDm MOD UDINT#65536);

GVL_StopMachine.a_wShiftAreaX100[0] :=
    UDINT_TO_WORD(GVL_Runtime.stStopMachine.udiShiftAreaX100 / UDINT#65536);
GVL_StopMachine.a_wShiftAreaX100[1] :=
    UDINT_TO_WORD(GVL_Runtime.stStopMachine.udiShiftAreaX100 MOD UDINT#65536);

GVL_StopMachine.wSpeedDmPerMin := UINT_TO_WORD(GVL_Runtime.stStopMachine.uiSpeedDmPerMin);
GVL_StopMachine.wChangeoverRemainingTenthsMin :=
    UINT_TO_WORD(GVL_Runtime.stStopMachine.uiChangeoverRemainingTenthsMin);
GVL_StopMachine.wChangeoverSetpointTenthsMin :=
    UINT_TO_WORD(PersistentVars.stStopMachine.uiChangeoverSetpointTenthsMin);
GVL_StopMachine.wStartDetectLengthDm :=
    UINT_TO_WORD(PersistentVars.stStopMachine.uiStartDetectLengthDm);
GVL_StopMachine.wAreaCoefficientX100 :=
    UINT_TO_WORD(PersistentVars.stStopMachine.uiAreaCoefficientX100);
GVL_StopMachine.wLastBreakPoint :=
    USINT_TO_WORD(GVL_Runtime.stStopMachine.usiLastBreakPoint);
GVL_StopMachine.wLastBreakSide :=
    USINT_TO_WORD(GVL_Runtime.stStopMachine.usiLastBreakSide);
GVL_StopMachine.wLastBreakReason :=
    USINT_TO_WORD(GVL_Runtime.stStopMachine.usiLastBreakReason);

IF GVL_Runtime.stStopMachine.xPackingComplete THEN
    GVL_StopMachine.wPackingComplete := WORD#1;
ELSE
    GVL_StopMachine.wPackingComplete := WORD#0;
END_IF;

GVL_StopMachine.wLastCommandResult := GVL_Runtime.stStopMachine.wLastCommandResult;
GVL_StopMachine.wLastProcessedSequence := GVL_Runtime.stStopMachine.wLastProcessedSequence;

// Защитный инвариант: Стопмашина работает только с отчётом и никогда
// не выдаёт команд физическому оборудованию.
GVL_StopMachine.wPhysicalControlEnabled := WORD#0;

GVL_StopMachine.a_wOrderDatabaseId[0] :=
    UDINT_TO_WORD(GVL_Runtime.stStopMachine.udiOrderDatabaseId / UDINT#65536);
GVL_StopMachine.a_wOrderDatabaseId[1] :=
    UDINT_TO_WORD(GVL_Runtime.stStopMachine.udiOrderDatabaseId MOD UDINT#65536);

GVL_StopMachine.a_wOrderTechnicalCard[0] :=
    UDINT_TO_WORD(GVL_Runtime.stStopMachine.udiOrderTechnicalCard / UDINT#65536);
GVL_StopMachine.a_wOrderTechnicalCard[1] :=
    UDINT_TO_WORD(GVL_Runtime.stStopMachine.udiOrderTechnicalCard MOD UDINT#65536);

GVL_StopMachine.wOrderSourceShift :=
    UINT_TO_WORD(GVL_Runtime.stStopMachine.uiOrderSourceShift);
GVL_StopMachine.wOrderNominalSpeed :=
    UINT_TO_WORD(GVL_Runtime.stStopMachine.uiOrderNominalSpeed);
GVL_StopMachine.wOperatorNumber :=
    UINT_TO_WORD(GVL_Runtime.stStopMachine.uiOperatorNumber);


GVL_Diagnostics.stSystem.xAnyConfigFault :=
    GVL_Diagnostics.stSystem.xAnyConfigFault
    OR GVL_Runtime.stStopMachine.xConfigFault;

// ============================================================
// 7а. Постоянный журнал переходов ЛГК для подтверждаемой отправки
// ============================================================

a_xStopJournalEnqueue[1] := FALSE;
a_xStopJournalEnqueue[2] := FALSE;
a_stStopJournalEnqueue[1] := stEmptyStopJournalEvent;
a_stStopJournalEnqueue[2] := stEmptyStopJournalEvent;

IF xStopJournalFirstCycle THEN
    wStopPreviousState := GVL_Runtime.stStopMachine.wStateCode;
    wStopPreviousShift := USINT_TO_WORD(GVL_Runtime.stShiftState.usiCurrentShift);
    udiStopPreviousOrderDbId := GVL_Runtime.stStopMachine.udiOrderDatabaseId;
    xStopJournalFirstCycle := FALSE;
ELSE
    // На границе смены сохраняем завершённую смену до обнуления её итогов.
    IF GVL_Runtime.stShiftState.xShiftChanged
       AND (wStopPreviousShift >= WORD#1)
       AND (wStopPreviousShift <= WORD#2) THEN
        stStopEvent.wKind := WORD#2;
        stStopEvent.wStateCode := WORD#32768;
        stStopEvent.wShiftNumber := wStopPreviousShift;
        stStopEvent.udiOrderNumber := stStopBeforeUpdate.udiOrderNumber;
        stStopEvent.udiOrderLengthDm := stStopBeforeUpdate.udiCurrentOrderLengthDm;
        stStopEvent.udiOrderAreaX100 := stStopBeforeUpdate.udiCurrentOrderAreaX100;
        stStopEvent.udiShiftLengthDm := stStopBeforeUpdate.udiShiftLengthDm;
        stStopEvent.udiShiftAreaX100 := stStopBeforeUpdate.udiShiftAreaX100;
        stStopEvent.wSpeedDmPerMin := UINT_TO_WORD(stStopBeforeUpdate.uiSpeedDmPerMin);
        stStopEvent.wOperatorNumber := UINT_TO_WORD(stStopBeforeUpdate.uiOperatorNumber);
        stStopEvent.wChangeoverSetpointTenthsMin :=
            UINT_TO_WORD(PersistentVars.stStopMachine.uiChangeoverSetpointTenthsMin);
        stStopEvent.wAlarmBits := stStopBeforeUpdate.wAlarmBits;
        stStopEvent.wBreakPoint := USINT_TO_WORD(stStopBeforeUpdate.usiLastBreakPoint);
        stStopEvent.wBreakSide := USINT_TO_WORD(stStopBeforeUpdate.usiLastBreakSide);
        stStopEvent.wBreakReason := USINT_TO_WORD(stStopBeforeUpdate.usiLastBreakReason);
        IF GVL_Runtime.stShiftState.xRtcValid THEN
            stStopEvent.udiTimestampUtc := GVL_Runtime.stShiftState.udiTimestampUtc;
        ELSE
            stStopEvent.udiTimestampUtc := UDINT#0;
        END_IF;
        a_stStopJournalEnqueue[1] := stStopEvent;
        a_xStopJournalEnqueue[1] := TRUE;
    END_IF;

    // Любой новый код, новый заказ или смена подробностей обрыва — одно событие.
    IF ((GVL_Runtime.stStopMachine.wStateCode <> wStopPreviousState)
        OR (GVL_Runtime.stStopMachine.udiOrderDatabaseId <> udiStopPreviousOrderDbId)
        OR fbStopMachine.q_xBreakRecorded)
       AND (GVL_Runtime.stStopMachine.wStateCode <> WORD#0) THEN
        stStopEvent := stEmptyStopJournalEvent;
        IF GVL_Runtime.stStopMachine.udiOrderDatabaseId <> udiStopPreviousOrderDbId THEN
            stStopEvent.wKind := WORD#3;
        ELSE
            stStopEvent.wKind := WORD#1;
        END_IF;
        stStopEvent.wStateCode := GVL_Runtime.stStopMachine.wStateCode;
        stStopEvent.wShiftNumber := USINT_TO_WORD(GVL_Runtime.stShiftState.usiCurrentShift);
        stStopEvent.udiOrderNumber := GVL_Runtime.stStopMachine.udiOrderNumber;
        stStopEvent.udiOrderLengthDm := GVL_Runtime.stStopMachine.udiCurrentOrderLengthDm;
        stStopEvent.udiOrderAreaX100 := GVL_Runtime.stStopMachine.udiCurrentOrderAreaX100;
        stStopEvent.udiShiftLengthDm := GVL_Runtime.stStopMachine.udiShiftLengthDm;
        stStopEvent.udiShiftAreaX100 := GVL_Runtime.stStopMachine.udiShiftAreaX100;
        stStopEvent.wSpeedDmPerMin := UINT_TO_WORD(GVL_Runtime.stStopMachine.uiSpeedDmPerMin);
        stStopEvent.wOperatorNumber := UINT_TO_WORD(GVL_Runtime.stStopMachine.uiOperatorNumber);
        stStopEvent.wChangeoverSetpointTenthsMin :=
            UINT_TO_WORD(PersistentVars.stStopMachine.uiChangeoverSetpointTenthsMin);
        stStopEvent.wAlarmBits := GVL_Runtime.stStopMachine.wAlarmBits;
        stStopEvent.wBreakPoint := USINT_TO_WORD(GVL_Runtime.stStopMachine.usiLastBreakPoint);
        stStopEvent.wBreakSide := USINT_TO_WORD(GVL_Runtime.stStopMachine.usiLastBreakSide);
        stStopEvent.wBreakReason := USINT_TO_WORD(GVL_Runtime.stStopMachine.usiLastBreakReason);
        IF GVL_Runtime.stShiftState.xRtcValid THEN
            stStopEvent.udiTimestampUtc := GVL_Runtime.stShiftState.udiTimestampUtc;
        ELSE
            stStopEvent.udiTimestampUtc := UDINT#0;
        END_IF;
        a_stStopJournalEnqueue[2] := stStopEvent;
        a_xStopJournalEnqueue[2] := TRUE;
    END_IF;

    wStopPreviousState := GVL_Runtime.stStopMachine.wStateCode;
    wStopPreviousShift := USINT_TO_WORD(GVL_Runtime.stShiftState.usiCurrentShift);
    udiStopPreviousOrderDbId := GVL_Runtime.stStopMachine.udiOrderDatabaseId;
END_IF;

IF GVL_Runtime.stStopMachine.wStateCode <> WORD#0 THEN
    PersistentVars.stStopJournal.wLastState := GVL_Runtime.stStopMachine.wStateCode;
END_IF;

udiStopAckEventId :=
    WORD_TO_UDINT(GVL_StopJournal.a_wAckEventId[0]) * UDINT#65536
    + WORD_TO_UDINT(GVL_StopJournal.a_wAckEventId[1]);

fbStopJournalQueue(
    i_a_xEnqueue := a_xStopJournalEnqueue,
    i_a_stEvent := a_stStopJournalEnqueue,
    i_udiAckEventId := udiStopAckEventId,
    i_wAckCommand := GVL_StopJournal.wAckCommand,
    iq_a_stQueue := PersistentVars.stStopJournal.a_stQueue,
    iq_uiHead := PersistentVars.stStopJournal.uiHead,
    iq_uiTail := PersistentVars.stStopJournal.uiTail,
    iq_uiCount := PersistentVars.stStopJournal.uiCount,
    iq_udiNextId := PersistentVars.stStopJournal.udiNextEventId,
    iq_udiOverflow := PersistentVars.stStopJournal.udiOverflowCount
);

IF fbStopJournalQueue.q_xAckConsumed THEN
    GVL_StopJournal.wAckCommand := WORD#0;
    IF fbStopJournalQueue.q_xAckAccepted THEN
        GVL_StopJournal.wLastAckResult := WORD#1;
    ELSE
        GVL_StopJournal.wLastAckResult := WORD#2;
    END_IF;
END_IF;

GVL_StopJournal.wSignature := WORD#16#534A;
GVL_StopJournal.wVersion := WORD#1;
GVL_StopJournal.a_wEventId[0] :=
    UDINT_TO_WORD(fbStopJournalQueue.q_stHead.udiEventId / UDINT#65536);
GVL_StopJournal.a_wEventId[1] :=
    UDINT_TO_WORD(fbStopJournalQueue.q_stHead.udiEventId MOD UDINT#65536);
GVL_StopJournal.a_wTimestampUtc[0] :=
    UDINT_TO_WORD(fbStopJournalQueue.q_stHead.udiTimestampUtc / UDINT#65536);
GVL_StopJournal.a_wTimestampUtc[1] :=
    UDINT_TO_WORD(fbStopJournalQueue.q_stHead.udiTimestampUtc MOD UDINT#65536);
GVL_StopJournal.wKind := fbStopJournalQueue.q_stHead.wKind;
GVL_StopJournal.wStateCode := fbStopJournalQueue.q_stHead.wStateCode;
GVL_StopJournal.wShiftNumber := fbStopJournalQueue.q_stHead.wShiftNumber;
GVL_StopJournal.a_wOrderNumber[0] :=
    UDINT_TO_WORD(fbStopJournalQueue.q_stHead.udiOrderNumber / UDINT#65536);
GVL_StopJournal.a_wOrderNumber[1] :=
    UDINT_TO_WORD(fbStopJournalQueue.q_stHead.udiOrderNumber MOD UDINT#65536);
GVL_StopJournal.a_wOrderLengthDm[0] :=
    UDINT_TO_WORD(fbStopJournalQueue.q_stHead.udiOrderLengthDm / UDINT#65536);
GVL_StopJournal.a_wOrderLengthDm[1] :=
    UDINT_TO_WORD(fbStopJournalQueue.q_stHead.udiOrderLengthDm MOD UDINT#65536);
GVL_StopJournal.a_wOrderAreaX100[0] :=
    UDINT_TO_WORD(fbStopJournalQueue.q_stHead.udiOrderAreaX100 / UDINT#65536);
GVL_StopJournal.a_wOrderAreaX100[1] :=
    UDINT_TO_WORD(fbStopJournalQueue.q_stHead.udiOrderAreaX100 MOD UDINT#65536);
GVL_StopJournal.wSpeedDmPerMin := fbStopJournalQueue.q_stHead.wSpeedDmPerMin;
GVL_StopJournal.wOperatorNumber := fbStopJournalQueue.q_stHead.wOperatorNumber;
GVL_StopJournal.wChangeoverSetpointTenthsMin :=
    fbStopJournalQueue.q_stHead.wChangeoverSetpointTenthsMin;
GVL_StopJournal.wAlarmBits := fbStopJournalQueue.q_stHead.wAlarmBits;
GVL_StopJournal.wBreakPoint := fbStopJournalQueue.q_stHead.wBreakPoint;
GVL_StopJournal.wBreakSide := fbStopJournalQueue.q_stHead.wBreakSide;
GVL_StopJournal.wBreakReason := fbStopJournalQueue.q_stHead.wBreakReason;
GVL_StopJournal.a_wShiftLengthDm[0] :=
    UDINT_TO_WORD(fbStopJournalQueue.q_stHead.udiShiftLengthDm / UDINT#65536);
GVL_StopJournal.a_wShiftLengthDm[1] :=
    UDINT_TO_WORD(fbStopJournalQueue.q_stHead.udiShiftLengthDm MOD UDINT#65536);
GVL_StopJournal.a_wShiftAreaX100[0] :=
    UDINT_TO_WORD(fbStopJournalQueue.q_stHead.udiShiftAreaX100 / UDINT#65536);
GVL_StopJournal.a_wShiftAreaX100[1] :=
    UDINT_TO_WORD(fbStopJournalQueue.q_stHead.udiShiftAreaX100 MOD UDINT#65536);
IF fbStopJournalQueue.q_xReady THEN
    GVL_StopJournal.wEventReady := WORD#1;
ELSE
    GVL_StopJournal.wEventReady := WORD#0;
END_IF;
GVL_StopJournal.wQueueCount := UINT_TO_WORD(PersistentVars.stStopJournal.uiCount);
IF fbStopJournalQueue.q_xStorageFault THEN
    GVL_StopJournal.wQueueStatus := WORD#3;
ELSIF fbStopJournalQueue.q_xIdExhausted THEN
    GVL_StopJournal.wQueueStatus := WORD#4;
ELSIF PersistentVars.stStopJournal.udiOverflowCount > UDINT#0 THEN
    GVL_StopJournal.wQueueStatus := WORD#2;
ELSIF fbStopJournalQueue.q_xFull THEN
    GVL_StopJournal.wQueueStatus := WORD#1;
ELSE
    GVL_StopJournal.wQueueStatus := WORD#0;
END_IF;
GVL_StopJournal.a_wOverflowCount[0] :=
    UDINT_TO_WORD(PersistentVars.stStopJournal.udiOverflowCount / UDINT#65536);
GVL_StopJournal.a_wOverflowCount[1] :=
    UDINT_TO_WORD(PersistentVars.stStopJournal.udiOverflowCount MOD UDINT#65536);
GVL_StopJournal.wHeartbeat := GVL_StopMachine.wPlcHeartbeat;


// ============================================================
// 8. Центральная Haiwell A10-W: только чтение
// ============================================================

// Связь со сборщиком считается установленной только после первого изменения
// его heartbeat и пока между изменениями прошло не более пяти секунд.
xCollectorHeartbeatChanged :=
    GVL_SCADA.wCollectorHeartbeat <> wCollectorHeartbeatPrevious;

IF xCollectorHeartbeatChanged THEN
    wCollectorHeartbeatPrevious := GVL_SCADA.wCollectorHeartbeat;
    xCollectorHeartbeatSeen := TRUE;
END_IF;

fbCollectorTimeout(
    IN := NOT xCollectorHeartbeatChanged,
    PT := T#5s
);

xCollectorConnected :=
    xCollectorHeartbeatSeen AND NOT fbCollectorTimeout.Q;


GVL_HAIWELL.wHmiSignature := WORD#16#484D; // ASCII "HM".
GVL_HAIWELL.wHmiProtocolVersion := GVL_Constants.c_wHaiwellProtocolVersion;
GVL_HAIWELL.wPlcHeartbeat := GVL_StopMachine.wPlcHeartbeat;
GVL_HAIWELL.wCurrentShift :=
    USINT_TO_WORD(GVL_Runtime.stShiftState.usiCurrentShift);
GVL_HAIWELL.wLocalHour :=
    UINT_TO_WORD(GVL_Runtime.stShiftState.uiLocalHour);
GVL_HAIWELL.wLocalMinute :=
    UINT_TO_WORD(GVL_Runtime.stShiftState.uiLocalMinute);
GVL_HAIWELL.wLocalYear :=
    UINT_TO_WORD(GVL_Runtime.stShiftState.uiLocalYear);
GVL_HAIWELL.wLocalMonth :=
    UINT_TO_WORD(GVL_Runtime.stShiftState.uiLocalMonth);
GVL_HAIWELL.wLocalDay :=
    UINT_TO_WORD(GVL_Runtime.stShiftState.uiLocalDay);
GVL_HAIWELL.wEventQueueCount := GVL_SCADA.wQueueCount;
GVL_HAIWELL.wEventQueueStatus := GVL_SCADA.wQueueStatus;
GVL_HAIWELL.wLastAckResult := GVL_SCADA.wLastAckResult;


// Системные биты: активность PLC, RTC, сборщик, очередь и конфигурация.
GVL_HAIWELL.wSystemStatusBits := WORD#16#0001;
IF GVL_Runtime.stShiftState.xRtcValid THEN
    GVL_HAIWELL.wSystemStatusBits :=
        GVL_HAIWELL.wSystemStatusBits OR WORD#16#0002;
END_IF;
IF xCollectorConnected THEN
    GVL_HAIWELL.wSystemStatusBits :=
        GVL_HAIWELL.wSystemStatusBits OR WORD#16#0004;
END_IF;
IF (GVL_SCADA.wQueueStatus = WORD#3)
   OR (GVL_SCADA.wQueueStatus = WORD#4) THEN
    GVL_HAIWELL.wSystemStatusBits :=
        GVL_HAIWELL.wSystemStatusBits OR WORD#16#0008;
END_IF;
IF GVL_SCADA.wQueueStatus = WORD#2 THEN
    GVL_HAIWELL.wSystemStatusBits :=
        GVL_HAIWELL.wSystemStatusBits OR WORD#16#0010;
END_IF;
IF GVL_Diagnostics.stSystem.xAnyConfigFault
   OR GVL_Diagnostics.stSystem.xAnyHscFault THEN
    GVL_HAIWELL.wSystemStatusBits :=
        GVL_HAIWELL.wSystemStatusBits OR WORD#16#0020;
END_IF;


uliShiftRawTotalMm := ULINT#0;

FOR iRoll := 1 TO GVL_Constants.c_iRollChannelCount DO
    // Текущий и предыдущий рулон уже безопасно упакованы для DWIN.
    GVL_HAIWELL.a_wCurrentLengthX10[iRoll, 0] :=
        a_fbDwinDataPacker[iRoll].q_wCurrentHigh;
    GVL_HAIWELL.a_wCurrentLengthX10[iRoll, 1] :=
        a_fbDwinDataPacker[iRoll].q_wCurrentLow;
    GVL_HAIWELL.a_wPreviousLengthX10[iRoll, 0] :=
        a_fbDwinDataPacker[iRoll].q_wPreviousHigh;
    GVL_HAIWELL.a_wPreviousLengthX10[iRoll, 1] :=
        a_fbDwinDataPacker[iRoll].q_wPreviousLow;

    GVL_HAIWELL.a_wUnwindStatus[iRoll] := WORD#0;
    IF NOT PersistentVars.a_stRollState[iRoll].xConfigFault THEN
        GVL_HAIWELL.a_wUnwindStatus[iRoll] :=
            GVL_HAIWELL.a_wUnwindStatus[iRoll] OR WORD#16#0001;
    END_IF;
    IF a_xHaiwellActivitySeen[iRoll] THEN
        GVL_HAIWELL.a_wUnwindStatus[iRoll] :=
            GVL_HAIWELL.a_wUnwindStatus[iRoll] OR WORD#16#0002;
    END_IF;
    IF a_fbSpliceFilter[iRoll].q_xFiltered THEN
        GVL_HAIWELL.a_wUnwindStatus[iRoll] :=
            GVL_HAIWELL.a_wUnwindStatus[iRoll] OR WORD#16#0004;
    END_IF;
    IF a_xHaiwellResetSeen[iRoll] THEN
        GVL_HAIWELL.a_wUnwindStatus[iRoll] :=
            GVL_HAIWELL.a_wUnwindStatus[iRoll] OR WORD#16#0008;
    END_IF;
    IF PersistentVars.a_stRollState[iRoll].xConfigFault THEN
        GVL_HAIWELL.a_wUnwindStatus[iRoll] :=
            GVL_HAIWELL.a_wUnwindStatus[iRoll] OR WORD#16#0010;
    END_IF;

    // Состояние строки обзора: жёлтая полуволна трёхкратной индикации
    // SPLICE/RESET имеет приоритет над признаком движения.
    IF a_fbHaiwellAttentionFlash[iRoll].q_xFlashOn THEN
        GVL_HAIWELL.a_wUnwindDisplayState[iRoll] := WORD#2;
    ELSIF a_xHaiwellActivitySeen[iRoll] THEN
        GVL_HAIWELL.a_wUnwindDisplayState[iRoll] := WORD#1;
    ELSE
        GVL_HAIWELL.a_wUnwindDisplayState[iRoll] := WORD#0;
    END_IF;

    CASE PersistentVars.a_stRollState[iRoll].eLastEndReason OF
        ROLL_END_SPLICE:
            GVL_HAIWELL.a_wLastEndReason[iRoll] := WORD#1;
        ROLL_END_RESET:
            GVL_HAIWELL.a_wLastEndReason[iRoll] := WORD#2;
        ELSE
            GVL_HAIWELL.a_wLastEndReason[iRoll] := WORD#0;
    END_CASE;

    // Отброшенная длина: миллиметры -> 0,1 м, с насыщением UDINT.
    uliHaiwellValueX10 :=
        PersistentVars.a_stRollState[iRoll].uliDiscardedTotalLengthMm / ULINT#100;
    IF uliHaiwellValueX10 <= ULINT#4294967295 THEN
        udiHaiwellValueX10 := ULINT_TO_UDINT(uliHaiwellValueX10);
    ELSE
        udiHaiwellValueX10 := UDINT#4294967295;
        GVL_Diagnostics.stSystem.xAnyConfigFault := TRUE;
        GVL_HAIWELL.wSystemStatusBits :=
            GVL_HAIWELL.wSystemStatusBits OR WORD#16#0020;
    END_IF;
    GVL_HAIWELL.a_wDiscardedLengthX10[iRoll, 0] :=
        UDINT_TO_WORD(udiHaiwellValueX10 / UDINT#65536);
    GVL_HAIWELL.a_wDiscardedLengthX10[iRoll, 1] :=
        UDINT_TO_WORD(udiHaiwellValueX10 MOD UDINT#65536);


    // Расход сырья этого раската за смену: импульсы -> мм -> 0,1 м.
    uliShiftLengthMm :=
        (PersistentVars.a_uliShiftRollPulses[iRoll]
         * UDINT_TO_ULINT(GVL_Constants.c_udiWheelCircumferenceMm))
        / UDINT_TO_ULINT(GVL_Constants.c_udiEncoderPulsesPerRevolution);

    IF uliShiftRawTotalMm
       <= (ULINT#18446744073709551615 - uliShiftLengthMm) THEN
        uliShiftRawTotalMm := uliShiftRawTotalMm + uliShiftLengthMm;
    ELSE
        uliShiftRawTotalMm := ULINT#18446744073709551615;
        GVL_Diagnostics.stSystem.xAnyConfigFault := TRUE;
    END_IF;

    uliHaiwellValueX10 := uliShiftLengthMm / ULINT#100;
    IF uliHaiwellValueX10 <= ULINT#4294967295 THEN
        udiHaiwellValueX10 := ULINT_TO_UDINT(uliHaiwellValueX10);
    ELSE
        udiHaiwellValueX10 := UDINT#4294967295;
        GVL_Diagnostics.stSystem.xAnyConfigFault := TRUE;
    END_IF;
    GVL_HAIWELL.a_wShiftRollLengthX10[iRoll, 0] :=
        UDINT_TO_WORD(udiHaiwellValueX10 / UDINT#65536);
    GVL_HAIWELL.a_wShiftRollLengthX10[iRoll, 1] :=
        UDINT_TO_WORD(udiHaiwellValueX10 MOD UDINT#65536);
END_FOR;


// Общий выпуск шестого энкодера: миллиметры -> 0,1 м.
uliHaiwellValueX10 := GVL_Runtime.stLineState.uliTotalLengthMm / ULINT#100;
IF uliHaiwellValueX10 <= ULINT#4294967295 THEN
    udiHaiwellValueX10 := ULINT_TO_UDINT(uliHaiwellValueX10);
ELSE
    udiHaiwellValueX10 := UDINT#4294967295;
    GVL_Diagnostics.stSystem.xAnyConfigFault := TRUE;
    GVL_HAIWELL.wSystemStatusBits :=
        GVL_HAIWELL.wSystemStatusBits OR WORD#16#0020;
END_IF;
GVL_HAIWELL.a_wOutputTotalLengthX10[0] :=
    UDINT_TO_WORD(udiHaiwellValueX10 / UDINT#65536);
GVL_HAIWELL.a_wOutputTotalLengthX10[1] :=
    UDINT_TO_WORD(udiHaiwellValueX10 MOD UDINT#65536);

IF GVL_Runtime.stLineState.rSpeedMPerMin <= 0.0 THEN
    uiHaiwellSpeedX10 := UINT#0;
ELSIF GVL_Runtime.stLineState.rSpeedMPerMin >= 6553.5 THEN
    uiHaiwellSpeedX10 := UINT#65535;
ELSE
    uiHaiwellSpeedX10 :=
        REAL_TO_UINT(GVL_Runtime.stLineState.rSpeedMPerMin * 10.0);
END_IF;
GVL_HAIWELL.wOutputSpeedX10 := UINT_TO_WORD(uiHaiwellSpeedX10);

GVL_HAIWELL.wOutputStatus := WORD#0;
IF NOT GVL_Runtime.stLineState.xConfigFault THEN
    GVL_HAIWELL.wOutputStatus :=
        GVL_HAIWELL.wOutputStatus OR WORD#16#0001;
END_IF;
IF GVL_Runtime.stLineState.xMoving THEN
    GVL_HAIWELL.wOutputStatus :=
        GVL_HAIWELL.wOutputStatus OR WORD#16#0002;
END_IF;
IF GVL_Runtime.a_stHscState[6].xDataValid THEN
    GVL_HAIWELL.wOutputStatus :=
        GVL_HAIWELL.wOutputStatus OR WORD#16#0004;
END_IF;
IF GVL_Runtime.stLineState.xConfigFault THEN
    GVL_HAIWELL.wOutputStatus :=
        GVL_HAIWELL.wOutputStatus OR WORD#16#0010;
END_IF;

GVL_HAIWELL.a_wQueueOverflowCount[0] :=
    GVL_SCADA.a_wQueueOverflowCount[0];
GVL_HAIWELL.a_wQueueOverflowCount[1] :=
    GVL_SCADA.a_wQueueOverflowCount[1];
GVL_HAIWELL.wCollectorHeartbeat := GVL_SCADA.wCollectorHeartbeat;
GVL_HAIWELL.wReserved2157 := WORD#0;


// Выпуск за смену по шестому энкодеру.
uliShiftLengthMm :=
    (PersistentVars.uliShiftOutputPulses
     * UDINT_TO_ULINT(GVL_Constants.c_udiWheelCircumferenceMm))
    / UDINT_TO_ULINT(GVL_Constants.c_udiEncoderPulsesPerRevolution);

uliHaiwellValueX10 := uliShiftLengthMm / ULINT#100;
IF uliHaiwellValueX10 <= ULINT#4294967295 THEN
    udiHaiwellValueX10 := ULINT_TO_UDINT(uliHaiwellValueX10);
ELSE
    udiHaiwellValueX10 := UDINT#4294967295;
    GVL_Diagnostics.stSystem.xAnyConfigFault := TRUE;
END_IF;
GVL_HAIWELL.a_wShiftOutputLengthX10[0] :=
    UDINT_TO_WORD(udiHaiwellValueX10 / UDINT#65536);
GVL_HAIWELL.a_wShiftOutputLengthX10[1] :=
    UDINT_TO_WORD(udiHaiwellValueX10 MOD UDINT#65536);


// Суммарный расход сырья за смену по разрешённым раскатам.
uliHaiwellValueX10 := uliShiftRawTotalMm / ULINT#100;
IF uliHaiwellValueX10 <= ULINT#4294967295 THEN
    udiHaiwellValueX10 := ULINT_TO_UDINT(uliHaiwellValueX10);
ELSE
    udiHaiwellValueX10 := UDINT#4294967295;
    GVL_Diagnostics.stSystem.xAnyConfigFault := TRUE;
END_IF;
GVL_HAIWELL.a_wShiftRawTotalLengthX10[0] :=
    UDINT_TO_WORD(udiHaiwellValueX10 / UDINT#65536);
GVL_HAIWELL.a_wShiftRawTotalLengthX10[1] :=
    UDINT_TO_WORD(udiHaiwellValueX10 MOD UDINT#65536);


// Средняя скорость выпуска рассчитывается за фактически прошедшее время
// текущего сменного интервала, а не как среднее мгновенных отсчётов.
rShiftAverageSpeedMPerMin := 0.0;
IF GVL_Runtime.stShiftState.xRtcValid
   AND (GVL_Runtime.stShiftState.udiTimestampUtc
        > PersistentVars.udiShiftStartTimestampUtc) THEN

    udiShiftElapsedSeconds :=
        GVL_Runtime.stShiftState.udiTimestampUtc
        - PersistentVars.udiShiftStartTimestampUtc;

    rShiftAverageSpeedMPerMin :=
        ULINT_TO_REAL(uliShiftLengthMm)
        * 60.0
        / UDINT_TO_REAL(udiShiftElapsedSeconds)
        / 1000.0;

END_IF;

IF rShiftAverageSpeedMPerMin <= 0.0 THEN
    GVL_HAIWELL.wShiftAverageSpeedX10 := WORD#0;
ELSIF rShiftAverageSpeedMPerMin >= 6553.5 THEN
    GVL_HAIWELL.wShiftAverageSpeedX10 := WORD#65535;
ELSE
    GVL_HAIWELL.wShiftAverageSpeedX10 :=
        UINT_TO_WORD(REAL_TO_UINT(rShiftAverageSpeedMPerMin * 10.0));
END_IF;

GVL_HAIWELL.wShiftStatus := WORD#0;
IF GVL_Runtime.stShiftState.xRtcValid
   AND (PersistentVars.usiShiftAccumulatorNumber
        = GVL_Runtime.stShiftState.usiCurrentShift) THEN
    GVL_HAIWELL.wShiftStatus := WORD#16#0001;
END_IF;

GVL_HAIWELL.a_wReserved2208[0] := WORD#0;
GVL_HAIWELL.a_wReserved2208[1] := WORD#0;
GVL_HAIWELL.a_wReserved2226[0] := WORD#0;
GVL_HAIWELL.a_wReserved2226[1] := WORD#0;
GVL_HAIWELL.a_wReserved2226[2] := WORD#0;
GVL_HAIWELL.a_wReserved2226[3] := WORD#0;


// ============================================================
// 9. Общая диагностика выполнения программы
// ============================================================

IF GVL_Diagnostics.stSystem.uliProgramCycles < ULINT#18446744073709551615 THEN
    GVL_Diagnostics.stSystem.uliProgramCycles :=
        GVL_Diagnostics.stSystem.uliProgramCycles + ULINT#1;
ELSE
    GVL_Diagnostics.stSystem.uliProgramCycles := ULINT#0;
END_IF;

