InterfaceAsPlainText.html:xhtml:
VAR_GLOBAL CONSTANT
    c_iRollChannelCount              : INT   := 5;                    // Количество раскатов сырья.
    c_iHscChannelCount               : INT   := 6;                    // Пять раскатов и один энкодер линии.
    c_udiEncoderPulsesPerRevolution  : UDINT := UDINT#250;            // Импульсов энкодера за один оборот.
    c_udiWheelCircumferenceMm        : UDINT := UDINT#250;            // Окружность каждого мерного колеса, мм.
    c_udiHscCounterRange             : UDINT := UDINT#1000000000;     // Диапазон HSC: значения 0...999999999.
    c_udiMaxPulseDeltaPerCycle       : UDINT := UDINT#100000;         // Защита от ложного скачка или сброса HSC.
    c_tInputFilter                   : TIME  := T#50ms;                // Время подтверждения нажатия кнопки.
    c_uliManualResetMinLengthMm      : ULINT := ULINT#100000;         // Минимум 100 м для учёта ручного RESET.
    c_tSpeedSample                   : TIME  := T#1s;                  // Интервал обновления скорости линии.
    c_tHaiwellActivityHold           : TIME  := T#10s;                 // Удержание признака движения для медленного опроса HMI.
    c_tHaiwellFlashHalfPeriod        : TIME  := T#250ms;               // Три быстрые жёлтые вспышки: 0,25 с ВКЛ и 0,25 с ВЫКЛ.
    c_tHaiwellResetHold              : TIME  := T#3s;                  // Время показа состояния RESET на центральной HMI.
    c_usiShift_1_StartHour           : USINT := USINT#8;              // Начало первой смены, 08:00.
    c_usiShift_2_StartHour           : USINT := USINT#20;             // Начало второй смены, 20:00.
    c_udiShiftMaxIntervalSeconds     : UDINT := UDINT#43200;          // Максимум одного сменного интервала: 12 часов.
    c_udiLocalUtcOffsetSeconds       : UDINT := UDINT#10800;          // Брянск: UTC+3, то есть 3 часа.
    c_dwPersistentLayoutSignature    : DWORD := DWORD#16#4342504C;    // ASCII "CBPL": признак нашей структуры PERSISTENT.
    c_wPersistentLayoutVersion       : WORD  := WORD#2;                // Версия разметки постоянной памяти.
    c_wHaiwellProtocolVersion        : WORD  := WORD#2;                // Версия read-only карты центральной Haiwell.

    // Отдельный интерфейс Стопмашины ЛГК. Он не содержит номера линии.
    c_wStopMachineSignature          : WORD  := WORD#16#534D;         // ASCII "SM".
    c_wStopMachineProtocolVersion    : WORD  := WORD#2;
    c_wServerOrderApplyCommand       : WORD  := WORD#16#4F52;         // ASCII "OR": применить пакет заказа сервера.
    c_uiStopDefaultAreaCoefficientX100 : UINT := UINT#210;            // 2,10 м2 на метр.
    c_uiStopDefaultStartDetectLengthDm : UINT := UINT#500;            // 50,0 м.
    c_uiStopDefaultChangeoverTenthsMin : UINT := UINT#0;              // Таймер отключён до настройки.
    c_tStopNoFeedDelay               : TIME  := T#20s;

    c_wStopStateRunning              : WORD := WORD#1;
    c_wStopStateStopped              : WORD := WORD#2;
    c_wStopStateNoFeed               : WORD := WORD#8;
    c_wStopStateChangeover           : WORD := WORD#16;
    c_wStopStateProduction           : WORD := WORD#32;
    c_wStopStatePpr                  : WORD := WORD#64;
    c_wStopStateLunch                : WORD := WORD#128;
    c_wStopStateRepair               : WORD := WORD#256;
    c_wStopStateAlarm                : WORD := WORD#512;
    c_wStopStateTechnology           : WORD := WORD#1024;
    c_wStopStateBreak                : WORD := WORD#2048;

    c_wStopCommandStop               : WORD := WORD#1;
    c_wStopCommandStart              : WORD := WORD#2;
    c_wStopCommandChangeover         : WORD := WORD#3;
    c_wStopCommandProduction         : WORD := WORD#4;
    c_wStopCommandLunch              : WORD := WORD#5;
    c_wStopCommandPpr                : WORD := WORD#6;
    c_wStopCommandRepair             : WORD := WORD#7;
    c_wStopCommandAlarm              : WORD := WORD#8;
    c_wStopCommandTechnology         : WORD := WORD#9;
    c_wStopCommandBreak              : WORD := WORD#10;
    c_wStopCommandPackingComplete    : WORD := WORD#11;
    c_wStopCommandSetOperator        : WORD := WORD#12;
    c_wStopCommandApplySettings      : WORD := WORD#20;

    c_wStopResultNone                : WORD := WORD#0;
    c_wStopResultAccepted            : WORD := WORD#1;
    c_wStopResultInvalidCode         : WORD := WORD#2;
    c_wStopResultInvalidParameter    : WORD := WORD#3;
    c_wStopResultInvalidState        : WORD := WORD#4;                // Команда состояния противоречит движению энкодера.
END_VAR

VAR_GLOBAL
    a_wHmi1Tx : ARRAY[0..12] OF WORD; // Регистры VP 2000...200C панели раската №1.
    a_wHmi2Tx : ARRAY[0..12] OF WORD; // Регистры VP 2000...200C панели раската №2.
    a_wHmi3Tx : ARRAY[0..12] OF WORD; // Регистры VP 2000...200C панели раската №3.
    a_wHmi4Tx : ARRAY[0..12] OF WORD; // Регистры VP 2000...200C панели раската №4.
    a_wHmi5Tx : ARRAY[0..12] OF WORD; // Регистры VP 2000...200C панели раската №5.

    // Системный пакет установки встроенных часов DWIN через VP 009C...009F.
    a_wHmi1RtcSync : ARRAY[0..3] OF WORD;
    a_wHmi2RtcSync : ARRAY[0..3] OF WORD;
    a_wHmi3RtcSync : ARRAY[0..3] OF WORD;
    a_wHmi4RtcSync : ARRAY[0..3] OF WORD;
    a_wHmi5RtcSync : ARRAY[0..3] OF WORD;
END_VAR

VAR_GLOBAL a_wEventPacket AT %MW2000 : ARRAY[0..11] OF WORD; // Событие протокола v2: 12 последовательных слов. wEventReady AT %MW2012 : WORD; // 1 — пакет содержит событие, 0 — очередь пуста. wQueueCount AT %MW2013 : WORD; // Количество неподтверждённых событий в очереди. wQueueCapacity AT %MW2014 : WORD; // Полная ёмкость очереди, сейчас 128 событий. wQueueStatus AT %MW2015 : WORD; // 0 — пусто, 1 — есть данные, 2 — заполнена, 3 — ошибка хранилища, 4 — исчерпан EventId.
a_wAckEventId AT %MW2016 : ARRAY[0..1] OF WORD; // EventId UDINT, подтверждаемый сервером; старшее слово первым. wAckCommand AT %MW2018 : WORD; // Сервер записывает 16#A55A после сохранения события на диск. wCollectorHeartbeat AT %MW2019 : WORD; // Счётчик жизни службы-сборщика; записывается сервером. wLastAckResult AT %MW2020 : WORD; // 0 — подтверждений не было, 1 — принято, 2 — отклонено. a_wQueueOverflowCount AT %MW2021 : ARRAY[0..1] OF WORD; // Число событий, отвергнутых из-за полной очереди.
// Сервер -> PLC: новый заказ ЛГК. Параметры и sequence записываются первыми, // wOrderCommand = 16#4F52 записывается последним. PLC очищает команду сам. wOrderCommand AT %MW2030 : WORD; wOrderSequence AT %MW2031 : WORD; a_wOrderDatabaseId AT %MW2032 : ARRAY[0..1] OF WORD; // NumZ из ExternalProductionData, старшее слово первым. a_wOrderTechnicalCard AT %MW2034 : ARRAY[0..1] OF WORD; // NumTK, старшее слово первым. a_wOrderDisplayNumber AT %MW2036 : ARRAY[0..1] OF WORD; // Числовая часть Zakaz для экрана, старшее слово первым. wOrderSourceShift AT %MW2038 : WORD; // NumSM от сервера. wOrderNominalSpeed AT %MW2039 : WORD; // Efficiency, единицы исходной БД. wOrderChangeoverTenthsMin AT %MW2040 : WORD; // ReconfigurationT x 10.
// PLC -> сервер: результат применения заказа. wOrderApplyResult AT %MW2041 : WORD; // 0 — нет, 1 — принят, 2 — неверная команда, 3 — неверные данные. wLastOrderSequence AT %MW2042 : WORD; END_VAR

VAR_GLOBAL
    // Непрерывная read-only область Modbus TCP для центральной Haiwell A10-W.
    // Многословные значения передаются в порядке: старшее WORD, затем младшее WORD.

    wHmiSignature       AT %MW2100 : WORD; // 16#484D ('HM').
    wHmiProtocolVersion AT %MW2101 : WORD; // Версия карты.
    wPlcHeartbeat       AT %MW2102 : WORD; // Изменяется раз в секунду.
    wSystemStatusBits   AT %MW2103 : WORD; // Общие диагностические флаги.
    wCurrentShift       AT %MW2104 : WORD; // 1, 2 или 0 при недостоверном RTC.
    wLocalHour          AT %MW2105 : WORD; // 0...23.
    wLocalMinute        AT %MW2106 : WORD; // 0...59.
    wEventQueueCount    AT %MW2107 : WORD;
    wEventQueueStatus   AT %MW2108 : WORD;
    wLastAckResult      AT %MW2109 : WORD;

    a_wCurrentLengthX10  AT %MW2110 : ARRAY[1..5, 0..1] OF WORD;
    a_wPreviousLengthX10 AT %MW2120 : ARRAY[1..5, 0..1] OF WORD;
    a_wUnwindStatus      AT %MW2130 : ARRAY[1..5] OF WORD;
    a_wLastEndReason     AT %MW2135 : ARRAY[1..5] OF WORD;

    a_wOutputTotalLengthX10 AT %MW2140 : ARRAY[0..1] OF WORD;
    wOutputSpeedX10         AT %MW2142 : WORD;
    wOutputStatus           AT %MW2143 : WORD;
    a_wDiscardedLengthX10   AT %MW2144 : ARRAY[1..5, 0..1] OF WORD;
    a_wQueueOverflowCount   AT %MW2154 : ARRAY[0..1] OF WORD;
    wCollectorHeartbeat     AT %MW2156 : WORD;
    wReserved2157           AT %MW2157 : WORD;

    // Состояния, дата и накопители текущей смены.
    a_wUnwindDisplayState       AT %MW2200 : ARRAY[1..5] OF WORD;    // 0 — стоит, 1 — работает, 2 — жёлтая фаза SPLICE/RESET.
    wLocalYear                  AT %MW2205 : WORD;
    wLocalMonth                 AT %MW2206 : WORD;
    wLocalDay                   AT %MW2207 : WORD;
    a_wReserved2208             AT %MW2208 : ARRAY[0..1] OF WORD;
    a_wShiftOutputLengthX10     AT %MW2210 : ARRAY[0..1] OF WORD;
    wShiftAverageSpeedX10       AT %MW2212 : WORD;
    wShiftStatus                AT %MW2213 : WORD;                   // bit 0 — накопители достоверны.
    a_wShiftRollLengthX10       AT %MW2214 : ARRAY[1..5, 0..1] OF WORD;
    a_wShiftRawTotalLengthX10   AT %MW2224 : ARRAY[0..1] OF WORD;
    a_wReserved2226             AT %MW2226 : ARRAY[0..3] OF WORD;
END_VAR

VAR_GLOBAL
    // ========================================================
    // PLC -> HMI. Только чтение со стороны панели, MW2300...2359
    // ========================================================
    wSignature AT %MW2300 : WORD;
    wProtocolVersion AT %MW2301 : WORD;
    wPlcHeartbeat AT %MW2302 : WORD;
    wStateCode AT %MW2303 : WORD;
    wStatusBits AT %MW2304 : WORD;
    wAlarmBits AT %MW2305 : WORD;
    wShiftNumber AT %MW2306 : WORD;
    wLocalHour AT %MW2307 : WORD;
    wLocalMinute AT %MW2308 : WORD;
    wLocalSecond AT %MW2309 : WORD;
