    // ========================================================
    // HMI -> PLC. Панель пишет только MW2360...2399
    // Команда передаётся последней; sequence меняется для каждого действия.
    // ========================================================
    wCommandCode AT %MW2360 : WORD;
    wCommandSequence AT %MW2361 : WORD;
    wCommandParam0 AT %MW2362 : WORD;
    wCommandParam1 AT %MW2363 : WORD;
    wCommandParam2 AT %MW2364 : WORD;
