    a_wReservedWrite AT %MW2369 : ARRAY[0..30] OF WORD;
END_VAR

VAR_GLOBAL
    // Снимок первого события. PLC -> сервер, 2400...2422.
    wSignature AT %MW2400 : WORD;                 // 16#534A = SJ.
    wVersion AT %MW2401 : WORD;                   // Версия протокола 1.
    a_wEventId AT %MW2402 : ARRAY[0..1] OF WORD; // Старшее слово первым.
    a_wTimestampUtc AT %MW2404 : ARRAY[0..1] OF WORD;
