    wSpeedDmPerMin AT %MW2415 : WORD;
    wOperatorNumber AT %MW2416 : WORD;
    wChangeoverSetpointTenthsMin AT %MW2417 : WORD;
    wAlarmBits AT %MW2418 : WORD;
    wBreakPoint AT %MW2419 : WORD;
