    wLastAckResult AT %MW2432 : WORD;             // 0=нет, 1=принят, 2=отклонён.
    a_wOverflowCount AT %MW2433 : ARRAY[0..1] OF WORD;
    wHeartbeat AT %MW2435 : WORD;
    a_wReserved AT %MW2436 : ARRAY[0..23] OF WORD;
END_VAR
